window.__devGuideHTML = "<div class=\"section-header\">\n      <h2>🚀 快速开发指南</h2>\n      <div class=\"h2-meta\">\n        <span class=\"ctrl-badge\">必读</span>\n      </div>\n    </div>\n\n    <style>\n    .dev-step{background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:20px;margin-bottom:16px}\n    .dev-step h3{border-bottom:2px solid #409EFF;padding-bottom:8px;margin-bottom:12px;color:#1a1a2e;font-size:17px}\n    .dev-step h3 .step-num{display:inline-block;background:#409EFF;color:#fff;width:28px;height:28px;line-height:28px;text-align:center;border-radius:50%;margin-right:8px;font-size:14px}\n    .dev-step h4{font-size:14px;color:#333;margin:14px 0 6px}\n    .dev-step ul,.dev-step ol{padding-left:24px;margin:6px 0}\n    .dev-step li{margin:4px 0;font-size:13px;color:#555}\n    .dev-step .tip-box{background:#fff8e1;border-left:4px solid #ffc107;padding:10px 14px;margin:10px 0;border-radius:0 4px 4px 0;font-size:13px}\n    .dev-step .info-box{background:#e3f2fd;border-left:4px solid #2196F3;padding:10px 14px;margin:10px 0;border-radius:0 4px 4px 0;font-size:13px}\n    .dev-step .warn-box{background:#fce4ec;border-left:4px solid #f44336;padding:10px 14px;margin:10px 0;border-radius:0 4px 4px 0;font-size:13px}\n    .dev-step table{width:100%;border-collapse:collapse;font-size:13px;margin:10px 0}\n    .dev-step table th{background:#f5f5f5;padding:8px 12px;text-align:left;border:1px solid #e0e0e0;font-weight:600;font-size:12px}\n    .dev-step table td{padding:8px 12px;border:1px solid #e8eaed}\n    .dev-step code{background:#000;padding:2px 6px;border-radius:3px;font-size:13px;color:#409EFF}\n    .dev-step pre{margin:0}\n    .prompt-box{background:#1e1e1e;color:#d4d4d4;border-radius:6px;padding:14px;margin:10px 0;font-size:12px;line-height:1.6;position:relative;white-space:pre-wrap;word-break:break-all}\n    .prompt-box .copy-prompt{position:absolute;top:8px;right:8px;background:#555;border:1px solid #777;color:#fff;padding:2px 10px;border-radius:3px;cursor:pointer;font-size:11px}\n    .prompt-box .copy-prompt:hover{background:#777}\n    .checklist{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}\n    .checklist .check-item{background:#f5f5f5;padding:4px 10px;border-radius:4px;font-size:12px;color:#555}\n    .checklist .check-item::before{content:'☐ ';color:#aaa}\n    .checklist .check-item.done::before{content:'✅ '}\n    .tag{display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;margin-right:4px;font-weight:600}\n    .tag-new{background:#e8f5e9;color:#2e7d32}\n    .tag-old{background:#fff3e0;color:#e65100}\n    .tag-required{background:#fce4ec;color:#c62828}\n    .tag-optional{background:#e3f2fd;color:#1565c0}\n    </style>\n\n    <!-- 一、开发前准备 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">1</span>开发前准备</h3>\n      \n      <h4>1.1 必读文档</h4>\n      <ul>\n        <li><strong>本文档</strong>（webviewBridge API 文档）— 全部可用的 API 方法与命令</li>\n        <li><code>开发文档_控件交互规范.md</code> — 控件属性规范与约定</li>\n        <li><code>webviewBridge.js</code> 或 <code>webviewBridge_v2.js</code> — 桥接脚本源码</li>\n      </ul>\n\n      <h4>1.2 引入桥接脚本</h4>\n      <p>在 HTML 页面的 <code>&lt;head&gt;</code> 或 <code>&lt;body&gt;</code> 末尾引入：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML 骨架</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html lang=&quot;zh-CN&quot;&gt;\n&lt;head&gt;\n&lt;meta charset=&quot;UTF-8&quot;&gt;\n&lt;title&gt;我的页面&lt;/title&gt;\n&lt;style&gt;\n  /* 窗口拖拽控制 */\n  .pageContainer { app-region: drag; -webkit-app-region: drag; }\n  [data-drag-type] { app-region: no-drag; -webkit-app-region: no-drag; }\n  /* 你的其他样式 */\n&lt;/style&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;div class=&quot;pageContainer&quot; id=&quot;pageContainer&quot;&gt;\n    &lt;!-- 你的控件，每个都加上 data-drag-type --&gt;\n    &lt;button id=&quot;btn1&quot; data-drag-type=&quot;button&quot;&gt;点击&lt;/button&gt;\n  &lt;/div&gt;\n  &lt;script src=&quot;webviewBridge.js&quot;&gt;&lt;/script&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre></div>\n      <div class=\"info-box\">\n        <strong>🆕 五层智能识别：</strong>现在 <code>webviewBridge.js</code> 已内置<strong>五层智能识别机制</strong>（显式声明 → ARIA语义 → CSS类名 → DOM结构推断 → 原生标签）。纯 HTML 标签如 <code>&lt;button&gt;</code>、<code>&lt;input type=\"checkbox\"&gt;</code> 无需任何 <code>data-ctrl-type</code> 属性即可被自动识别并上报事件。智能辅助数据（customname/basictype）会自动从 label、placeholder、文本内容等推断填充。\n      </div>\n\n      <h4>1.3 图标占位符处理（重要）</h4>\n      <p>桥接脚本内置了 <strong>图标管理器（IconManager）</strong>，支持将 <code>[OK]</code>、<code>{ERROR}</code> 等占位符自动转换为对应的 Emoji 图标（如 ✅、❌）。同时，在向宿主上报数据时，会自动将 Emoji 转为 <code>[U+XXXX]</code> 格式，便于易语言等不支持 Unicode 的环境接收。</p>\n      <ul>\n        <li><strong>解析（页面显示）</strong>：<code>IconManager.parse(text)</code> 将占位符转为图标，通常无需手动调用，脚本会自动处理。</li>\n        <li><strong>转义（上报数据）</strong>：<code>IconManager.toText(html)</code> 将图标转为占位符或 <code>[U+XXXX]</code>，所有事件上报和 API 返回值均会自动执行此操作。</li>\n      </ul>\n      <div class=\"tip-box\">\n        <strong>💡 开发建议：</strong>在控件文本中直接使用占位符，如 <code>&lt;button&gt;[OK] 确定&lt;/button&gt;</code>，即可显示为“✅ 确定”。无需额外处理，桥接脚本会自动完成双向转换。\n      </div>\n\n      <h4>1.4 开发环境</h4>\n      <ul>\n        <li>任何文本编辑器或 IDE 均可</li>\n        <li>页面在宿主程序的 WebView2 控件中运行</li>\n        <li>调试时可使用浏览器 DevTools（F12）查看控制台日志</li>\n      </ul>\n    </div>\n\n    <!-- 二、开发步骤详解 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">2</span>开发步骤详解</h3>\n\n      <h4>第一步：创建 HTML 页面骨架</h4>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML 骨架</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html lang=&quot;zh-CN&quot;&gt;\n&lt;head&gt;\n&lt;meta charset=&quot;UTF-8&quot;&gt;\n&lt;title&gt;我的页面&lt;/title&gt;\n&lt;style&gt;\n  /* 你的样式 */\n&lt;/style&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;!-- 你的控件 --&gt;\n  &lt;script src=&quot;webviewBridge.js&quot;&gt;&lt;/script&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre></div>\n\n      <h4 style=\"margin-top:20px\">窗口拖拽控制（WebView2 专用）</h4>\n      <p>在 WebView2 中，通过 CSS 属性 <code>app-region</code> 控制窗口的可拖拽区域。请遵循以下规范：</p>\n      <ul>\n        <li><strong>页面容器（<code>.pageContainer</code>）</strong> 必须设置 <code>app-region: drag; -webkit-app-region: drag;</code>，使整个窗口可拖拽。</li>\n        <li><strong>所有可交互控件</strong>（按钮、输入框、下拉框、列表、表格等）必须设置 <code>app-region: no-drag; -webkit-app-region: no-drag;</code>，否则点击控件时会拖动窗口，导致无法触发事件。</li>\n        <li><strong>推荐做法</strong>：为每个控件添加 <code>data-drag-type</code> 属性（值任意，通常与控件类型相同），在全局 CSS 中统一设置 <code>[data-drag-type] { app-region: no-drag; -webkit-app-region: no-drag; }</code>。</li>\n        <li><strong>特殊场景：最大化按钮与 Snap Layout</strong>：在 Windows 11 中，为支持贴靠布局，最大化按钮自身必须为 <code>no-drag</code>，但其内部的 <code>&lt;span&gt;</code> 需设为 <code>drag</code>。示例：<code>.pageContainer [data-ctrl-type=\"titlebar_max\"] span { app-region: drag; -webkit-app-region: drag; }</code>。</li>\n      </ul>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">CSS 统一规则</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>.pageContainer { app-region: drag; -webkit-app-region: drag; }\n[data-drag-type] { app-region: no-drag; -webkit-app-region: no-drag; }\n/* 最大化按钮内部 span 允许拖拽以支持 Snap Layout */\n.pageContainer [data-ctrl-type=\"titlebar_max\"] span { app-region: drag; -webkit-app-region: drag; }</code></pre></div>\n      <div class=\"tip-box\"><strong>💡 注意：</strong>标题栏内的所有按钮（最小化、最大化、关闭）也需设为 <code>no-drag</code>，可通过 <code>[data-ctrl-type^=\"titlebar_\"]</code> 统一控制。</div>\n<h4>第二步：添加控件（三选一方式）</h4>\n\n      <table>\n        <thead><tr><th style=\"width:120px\">方式</th><th>适用场景</th><th>难度</th><th>识别层级</th><th>示例</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"tag tag-new\">首选</span><br/>标准 HTML</td>\n            <td>简单控件（按钮、输入框、复选框…）</td>\n            <td>★☆☆</td>\n            <td>Layer 5 原生标签</td>\n            <td><code>&lt;button id=\"btn1\"&gt;点击&lt;/button&gt;</code></td>\n          </tr>\n          <tr>\n            <td><span class=\"tag tag-new\">推荐</span><br/>CSS class 约定</td>\n            <td>复杂控件（列表、表格、树形…）</td>\n            <td>★★☆</td>\n            <td>Layer 3 CSS类名</td>\n            <td><code>&lt;ul class=\"listBox\" id=\"list1\"&gt;&lt;li&gt;A&lt;/li&gt;&lt;/ul&gt;</code></td>\n          </tr>\n          <tr>\n            <td><span class=\"tag tag-new\">语义化</span><br/>ARIA role</td>\n            <td>无障碍友好、语义化页面</td>\n            <td>★★☆</td>\n            <td>Layer 2 ARIA语义</td>\n            <td><code>&lt;div role=\"button\" id=\"btn1\"&gt;点击&lt;/div&gt;</code></td>\n          </tr>\n          <tr>\n            <td><span class=\"tag tag-old\">兼容</span><br/>显式声明</td>\n            <td>已有项目、需要精确控制</td>\n            <td>★★★</td>\n            <td>Layer 1 显式声明</td>\n            <td><code>&lt;button id=\"btn1\" data-ctrl-type=\"button\" data-name=\"按钮_1\"&gt;点击&lt;/button&gt;</code></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>第三步：绑定交互逻辑</h4>\n      <p>通过 <code>webviewBridge.api</code> 编写业务逻辑：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">JavaScript</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>// 按钮点击事件\nwebviewBridge.api.button.onClick(&#x27;btnSubmit&#x27;, function() {\n  var name = webviewBridge.api.input.getValue(&#x27;txtName&#x27;);\n  webviewBridge.api.public.setValue(&#x27;labelResult&#x27;, &#x27;你好，&#x27; + name);\n});</code></pre></div>\n\n      <h4>第四步：测试验证</h4>\n      <ul>\n        <li>在 WebView2 中加载页面，点击控件查看事件上报日志</li>\n        <li>使用宿主发送命令验证控件响应</li>\n        <li>检查浏览器控制台是否有报错</li>\n      </ul>\n\n      <h4>五层智能识别机制详解：</h4>\n      <p>webviewBridge.js 使用<strong>五层智能识别</strong>自动判断控件类型，优先级从高到低：</p>\n      <table>\n        <thead><tr><th>层级</th><th>识别方式</th><th>source值</th><th>说明</th><th>示例</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong style=\"color:#e74c3c;\">Layer 1</strong></td>\n            <td><code>data-ctrl-type</code> 属性</td>\n            <td><code>explicit</code></td>\n            <td>显式声明，最高优先级，向后兼容</td>\n            <td><code>&lt;div data-ctrl-type=\"listBox\"&gt;</code></td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:#e67e22;\">Layer 2</strong></td>\n            <td>ARIA <code>role</code> 属性</td>\n            <td><code>aria</code></td>\n            <td>Web 标准语义化识别，无障碍友好</td>\n            <td><code>&lt;div role=\"button\"&gt;</code></td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:#f1c40f;\">Layer 3</strong></td>\n            <td>CSS class 约定命名</td>\n            <td><code>css</code></td>\n            <td>特定 class 识别复杂控件及子元素</td>\n            <td><code>&lt;div class=\"listBox_item\"&gt;</code></td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:#2ecc71;\">Layer 4</strong></td>\n            <td>DOM 结构特征推断</td>\n            <td><code>structure</code></td>\n            <td>智能识别 ul/li、table/tr/td 等结构</td>\n            <td><code>&lt;ul&gt;&lt;li&gt;...&lt;/li&gt;&lt;/ul&gt;</code></td>\n          </tr>\n          <tr>\n            <td><strong style=\"color:#3498db;\">Layer 5</strong></td>\n            <td>原生 HTML 标签</td>\n            <td><code>native</code></td>\n            <td>兜底推断，零配置即用</td>\n            <td><code>&lt;button&gt;</code> → button</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"tip-box\">\n        <strong>💡 推荐做法：</strong>基础控件用原生标签（Layer 5），复杂控件用 CSS class 约定（Layer 3），特殊情况才用 <code>data-ctrl-type</code>（Layer 1）。层级越低，开发越简单，越符合 Web 标准。\n      </div>\n\n      <h4>智能辅助数据自动填充</h4>\n      <p>即使<strong>不设置</strong> <code>data-name</code> 和 <code>data-type</code>，桥接脚本也会<strong>自动推断</strong>，让上报消息更直观：</p>\n      <table>\n        <thead><tr><th>字段</th><th>推断优先级（从高到低）</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><code>customname</code><br/>（控件中文名）</td>\n            <td>data-name → aria-label → 关联label文字 → placeholder → 元素文本 → title/alt → id</td>\n          </tr>\n          <tr>\n            <td><code>basictype</code><br/>（基础类型中文名）</td>\n            <td>data-type → 自动从 ctrlType 映射中文名称（如 button→\"按钮\"）</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"info-box\">\n        <strong>✅ 最佳实践：</strong>建议给重要控件手动设置 <code>data-name</code>，这样宿主端显示的名称最准确。不设置也能用，脚本会自动猜。\n      </div>\n\n      <h4>第五步：基础控件开发示例</h4>\n      <p>以下示例<strong>只展示核心HTML结构</strong>，重点说明 webviewBridge.js 如何识别控件、上报什么数据。样式可根据需求自行编写。</p>\n      <div class=\"tip-box\">\n        <strong>核心要点：</strong>每个控件必须有唯一 <code>id</code>，用标准HTML标签即可被自动识别。<code>data-name</code> 建议设置，不设置会自动从 label/placeholder/文本 推断。\n      </div>\n\n      <!-- 5.1 按钮 -->\n      <h4 style=\"margin-top:16px\">5.1 按钮(Button)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;button id=\"btn_submit\" data-name=\"提交按钮\"&gt;提交&lt;/button&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 &lt;button&gt; 标签识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>button</code></td></tr>\n        <tr><td><strong>customname来源</strong></td><td>data-name → 按钮文本 → id</td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">点击后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"click\",\n  \"targetId\": \"btn_submit\",\n  \"ctrlType\": \"button\",\n  \"customname\": \"提交按钮\",   <span style=\"color:#2e7d32\">← 来自 data-name</span>\n  \"basictype\": \"按钮\",       <span style=\"color:#2e7d32\">← 自动映射中文</span>\n  \"source\": \"native\",       <span style=\"color:#2e7d32\">← Layer 5 原生标签</span>\n  \"data\": { \"value\": \"提交\", \"x\": 150, \"y\": 80 }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.button.setText('btn_submit', '保存')</code> — 设置文本<br/>\n        <code>webviewBridge.api.button.getText('btn_submit')</code> — 获取文本<br/>\n        <code>webviewBridge.api.public.setEnabled('btn_submit', false)</code> — 禁用\n      </div>\n\n      <!-- 5.2 输入框 -->\n      <h4 style=\"margin-top:16px\">5.2 输入框(Input)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;input id=\"inp_username\" type=\"text\" placeholder=\"请输入用户名\"&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 &lt;input type=\"text\"&gt; 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>inputText</code></td></tr>\n        <tr><td><strong>customname来源</strong></td><td>data-name → placeholder → 关联label文字 → id</td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">输入内容后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"change\",\n  \"targetId\": \"inp_username\",\n  \"ctrlType\": \"inputText\",\n  \"customname\": \"请输入用户名\", <span style=\"color:#2e7d32\">← 来自 placeholder</span>\n  \"basictype\": \"输入框\",\n  \"source\": \"native\",\n  \"data\": { \"value\": \"张三\" }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.input.setValue('inp_username', '张三')</code> — 设置值<br/>\n        <code>webviewBridge.api.input.getValue('inp_username')</code> — 获取值<br/>\n        <code>webviewBridge.api.input.setPlaceholder('inp_username', '请输入')</code> — 设置提示\n      </div>\n\n      <!-- 5.3 文本域 -->\n      <h4 style=\"margin-top:16px\">5.3 文本域(Textarea)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;textarea id=\"txt_remark\" placeholder=\"备注\" rows=\"4\"&gt;&lt;/textarea&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 &lt;textarea&gt; 标签识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>textarea</code></td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">上报事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"change\",\n  \"targetId\": \"txt_remark\",\n  \"ctrlType\": \"textarea\",\n  \"customname\": \"备注\",       <span style=\"color:#2e7d32\">← 来自 placeholder</span>\n  \"basictype\": \"文本域\",\n  \"source\": \"native\",\n  \"data\": { \"value\": \"这是备注内容\" }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.textarea.setValue('txt_remark', '内容')</code> — 设置内容<br/>\n        <code>webviewBridge.api.textarea.getValue('txt_remark')</code> — 获取内容<br/>\n        <code>webviewBridge.api.textarea.setRows('txt_remark', 8)</code> — 设置行数\n      </div>\n\n      <!-- 5.4 复选框 -->\n      <h4 style=\"margin-top:16px\">5.4 复选框(Checkbox)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;label&gt;&lt;input id=\"chk_agree\" type=\"checkbox\"&gt; 同意协议&lt;/label&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 input[type=checkbox] 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>checkbox</code></td></tr>\n        <tr><td><strong>customname来源</strong></td><td>data-name → label文字 → 后续文本 → id</td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">点击后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"click\",\n  \"targetId\": \"chk_agree\",\n  \"ctrlType\": \"checkbox\",\n  \"customname\": \"同意协议\",   <span style=\"color:#2e7d32\">← 来自 label 文字</span>\n  \"basictype\": \"复选框\",\n  \"source\": \"native\",\n  \"data\": { \"checked\": true, \"value\": \"on\" }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.checkbox.setChecked('chk_agree', true)</code> — 设置选中<br/>\n        <code>webviewBridge.api.checkbox.getChecked('chk_agree')</code> — 获取选中状态<br/>\n        <code>webviewBridge.api.public.toggle('chk_agree')</code> — 切换状态（需自行实现）\n      </div>\n\n      <!-- 5.5 单选框 -->\n      <h4 style=\"margin-top:16px\">5.5 单选框(Radio)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td>\n<pre style=\"margin:0;font-size:12px\">&lt;input id=\"rdo_male\" type=\"radio\" name=\"gender\"&gt; 男\n&lt;input id=\"rdo_female\" type=\"radio\" name=\"gender\"&gt; 女</pre>\n        </td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 input[type=radio] 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>radio</code></td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">上报事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"click\",\n  \"targetId\": \"rdo_male\",\n  \"ctrlType\": \"radio\",\n  \"customname\": \"男\",         <span style=\"color:#2e7d32\">← 来自后续文本</span>\n  \"basictype\": \"单选框\",\n  \"source\": \"native\",\n  \"data\": { \"checked\": true, \"groupName\": \"gender\" }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.radioGroup.setValue('gender', 'male')</code> — 选中某项（通过value）<br/>\n        <code>webviewBridge.api.radioGroup.getIndex('gender')</code> — 获取选中项索引\n      </div>\n\n      <!-- 5.6 下拉框 -->\n      <h4 style=\"margin-top:16px\">5.6 组合框(ComboBox)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td>\n<pre style=\"margin:0;font-size:12px\">&lt;select id=\"sel_city\"&gt;\n  &lt;option value=\"bj\"&gt;北京&lt;/option&gt;\n  &lt;option value=\"sh\"&gt;上海&lt;/option&gt;\n&lt;/select&gt;</pre>\n        </td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 &lt;select&gt; 标签识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>comboBox</code></td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">选择后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"change\",\n  \"targetId\": \"sel_city\",\n  \"ctrlType\": \"comboBox\",\n  \"customname\": \"sel_city\",    <span style=\"color:#e67e22\">← 无label时用id，建议设 data-name</span>\n  \"basictype\": \"组合框\",\n  \"source\": \"native\",\n  \"data\": { \"value\": \"bj\", \"text\": \"北京\", \"index\": 0 }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.comboBox.setValue('sel_city', 'bj')</code> — 设置选中值<br/>\n        <code>webviewBridge.api.comboBox.getValue('sel_city')</code> — 获取选中值<br/>\n        <code>webviewBridge.api.comboBox.addItem('sel_city', '广州', 'gz')</code> — 添加选项\n      </div>\n\n      <!-- 5.7 超链接 -->\n      <h4 style=\"margin-top:16px\">5.7 超链接(HyperLink)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;a href=\"#\" id=\"link_help\"&gt;帮助文档&lt;/a&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 &lt;a&gt; 标签识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>hyperLink</code></td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">点击后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"click\",\n  \"targetId\": \"link_help\",\n  \"ctrlType\": \"hyperLink\",\n  \"customname\": \"帮助文档\",   <span style=\"color:#2e7d32\">← 来自链接文本</span>\n  \"basictype\": \"超链接\",\n  \"source\": \"native\",\n  \"data\": { \"href\": \"#\", \"text\": \"帮助文档\" }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.hyperLink.setText('link_help', '查看帮助')</code> — 设置文字<br/>\n        <code>webviewBridge.api.hyperLink.setHref('link_help', 'https://...')</code> — 设置链接\n      </div>\n\n      <!-- 5.8 文本标签 -->\n      <h4 style=\"margin-top:16px\">5.8 文本标签(Label)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;span id=\"lbl_status\" data-name=\"状态\"&gt;就绪&lt;/span&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 &lt;span&gt; 标签识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>label</code></td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">上报事件数据（点击标签）</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"click\",\n  \"targetId\": \"lbl_status\",\n  \"ctrlType\": \"label\",\n  \"customname\": \"状态\",       <span style=\"color:#2e7d32\">← 来自 data-name</span>\n  \"basictype\": \"文本标签\",\n  \"source\": \"native\",\n  \"data\": { \"text\": \"就绪\" }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.label.setText('lbl_status', '加载中...')</code> — 设置文本<br/>\n        <code>webviewBridge.api.label.getText('lbl_status')</code> — 获取文本\n      </div>\n\n      <h4 style=\"margin-top:20px\">第六步：进阶控件开发示例</h4>\n      <p>进阶控件有的需要特定CSS class约定（Layer 3），有的用原生标签即可。</p>\n\n      <!-- 6.1 进度条 -->\n      <h4 style=\"margin-top:16px\">6.1 进度条(ProgressBar)</h4>\n      <p><strong>方式一</strong>（推荐）：用CSS class约定，结构识别更准确：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — CSS class 约定写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;div id=\"progress_load\" class=\"progressBar\" data-ctrl-type=\"progressBar\" data-editable=\"true\" data-name=\"加载进度\"&gt;\n  &lt;div class=\"progressBar_fill\" style=\"width:60%\"&gt;&lt;/div&gt;\n  &lt;span class=\"progressBar_text\"&gt;60%&lt;/span&gt;\n&lt;/div&gt;</code></pre></div>\n      <!-- ⚠️ 新增警告 -->\n      <div class=\"warn-box\">\n        <strong>⚠️ 关键提醒：</strong>进度条根容器 <strong>必须</strong> 添加 <code>data-ctrl-type=\"progressBar\"</code>，否则点击事件上报的 <code>data.value</code> 将始终为 <code>0</code>。此属性不影响识别，但影响数据提取。\n      </div>\n      <p><strong>方式二</strong>：原生 range 输入：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — 原生 input 写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;input id=\"progress_load\" type=\"range\" min=\"0\" max=\"100\" value=\"60\"&gt;</code></pre></div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>识别层级</strong></td><td>Layer 3（css）class约定 / Layer 5（native）原生input</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>progressBar</code></td></tr>\n        <tr><td><strong>可编辑</strong></td><td><code>data-editable=\"true\"</code> 时可点击调整进度</td></tr>\n      </table>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.progressBar.setValue('progress_load', 80)</code> — 设置进度<br/>\n        <code>webviewBridge.api.progressBar.getValue('progress_load')</code> — 获取进度\n      </div>\n\n      <!-- 6.2 日期时间选择器 -->\n      <h4 style=\"margin-top:16px\">6.2 日期时间选择器(DateTimePicker)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;input id=\"dt_date\" type=\"date\" data-name=\"选择日期\"&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 input[type=date/datetime-local] 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>datetimePicker</code></td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">选择后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"change\",\n  \"targetId\": \"dt_date\",\n  \"ctrlType\": \"datetimePicker\",\n  \"customname\": \"选择日期\",\n  \"basictype\": \"日期选择器\",\n  \"source\": \"native\",\n  \"data\": { \"value\": \"2025-06-15\" }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.dateTimePicker.setValue('dt_date', '2025-12-31')</code> — 设置日期<br/>\n        <code>webviewBridge.api.dateTimePicker.getValue('dt_date')</code> — 获取日期\n      </div>\n\n      <!-- 6.3 开关 -->\n      <h4 style=\"margin-top:16px\">6.3 开关(SwitchToggle)</h4>\n      <div class=\"warn-box\">\n        <strong>注意：</strong>开关需要显式声明 <code>data-ctrl-type=\"switchToggle\"</code>（Layer 1），因为原生 checkbox 和开关在HTML上无法区分。\n      </div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td>\n<pre style=\"margin:0;font-size:12px\">&lt;label id=\"sw_enable\" data-ctrl-type=\"switchToggle\" data-name=\"启用开关\"&gt;\n  &lt;input type=\"checkbox\"&gt; 启用功能\n&lt;/label&gt;</pre>\n        </td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 1（explicit）— 通过 data-ctrl-type 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>switchToggle</code></td></tr>\n      </table>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.switchToggle.setChecked('sw_enable', true)</code> — 打开/关闭<br/>\n        <code>webviewBridge.api.switchToggle.getChecked('sw_enable')</code> — 获取状态\n      </div>\n\n      <!-- 6.4 图片框 -->\n      <h4 style=\"margin-top:16px\">6.4 图片框(ImageBox)</h4>\n      <table>\n        <tr><td style=\"width:160px\"><strong>HTML写法</strong></td><td><code>&lt;img id=\"img_avatar\" src=\"avatar.png\" alt=\"用户头像\"&gt;</code></td></tr>\n        <tr><td><strong>识别层级</strong></td><td>Layer 5（native）— 通过 &lt;img&gt; 标签识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>imageBox</code></td></tr>\n        <tr><td><strong>customname来源</strong></td><td>data-name → alt → title → id</td></tr>\n      </table>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.imageBox.setSrc('img_avatar', 'new.png')</code> — 设置图片<br/>\n        <code>webviewBridge.api.imageBox.getSrc('img_avatar')</code> — 获取图片地址\n      </div>\n\n      <!-- 6.5 日志输出框 -->\n      <h4 style=\"margin-top:16px\">6.5 日志输出框(LogOutput)</h4>\n      <p>需要用 <code>logOutput</code> class 约定来识别（Layer 3）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — CSS class 约定写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;div id=\"log_main\" class=\"logOutput\" data-name=\"运行日志\"&gt;\n  &lt;div&gt;[INFO] 系统启动&lt;/div&gt;\n  &lt;div&gt;[INFO] 初始化完成&lt;/div&gt;\n&lt;/div&gt;</code></pre></div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>识别层级</strong></td><td>Layer 3（css）— 通过 logOutput class 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>logOutput</code></td></tr>\n      </table>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.logOutput.addLog('log_main', '[OK] 操作成功')</code> — 追加日志<br/>\n        <code>webviewBridge.api.logOutput.clearLog('log_main')</code> — 清空日志\n      </div>\n\n      <h4 style=\"margin-top:20px\">第七步：容器控件开发示例</h4>\n      <p>复杂控件（列表、表格、树形、标签页、卡片）推荐用 <strong>CSS class 约定</strong>（Layer 3）或 <strong>DOM结构推断</strong>（Layer 4）来识别，这样不需要硬编码 <code>data-ctrl-type</code>。</p>\n\n      <!-- 7.1 列表框 -->\n      <h4 style=\"margin-top:16px\">7.1 列表框(ListBox)</h4>\n      <p><strong>推荐写法</strong>：用原生 &lt;ul&gt;/&lt;li&gt;，自动结构识别（Layer 4）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — 原生 ul/li 写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;ul id=\"list_tasks\" class=\"listBox\" data-name=\"任务列表\"&gt;\n  &lt;li data-item-id=\"1\"&gt;任务一&lt;/li&gt;\n  &lt;li data-item-id=\"2\"&gt;任务二&lt;/li&gt;\n  &lt;li data-item-id=\"3\"&gt;任务三&lt;/li&gt;\n&lt;/ul&gt;</code></pre></div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>识别层级</strong></td><td>Layer 3（css class）+ Layer 4（结构推断）</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>listBox</code></td></tr>\n        <tr><td><strong>itemIndex</strong></td><td>自动从 li 的位置计算，不需要 data-item-index</td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">点击列表项后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"click\",\n  \"targetId\": \"list_tasks\",\n  \"ctrlType\": \"listBox\",\n  \"customname\": \"任务列表\",\n  \"basictype\": \"列表框\",\n  \"source\": \"css\",              <span style=\"color:#2e7d32\">← Layer 3 CSS class</span>\n  \"data\": {\n    \"itemIndex\": 1,             <span style=\"color:#2e7d32\">← 自动计算</span>\n    \"itemId\": \"2\",\n    \"text\": \"任务二\"\n  }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.listBox.addItem('list_tasks', '新任务')</code> — 添加项<br/>\n        <code>webviewBridge.api.listBox.removeItem('list_tasks', 0)</code> — 删除第1项<br/>\n        <code>webviewBridge.api.listBox.getItemText('list_tasks', 0)</code> — 获取项文本<br/>\n        <code>webviewBridge.api.listBox.clearItems('list_tasks')</code> — 清空\n      </div>\n\n      <!-- 7.2 数据表格 -->\n      <h4 style=\"margin-top:16px\">7.2 数据表格(DataGrid)</h4>\n      <p><strong>推荐写法</strong>：用原生 &lt;table&gt;，自动结构识别（Layer 4）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — 原生 table 写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;table id=\"grid_users\" class=\"dataGrid\" data-name=\"用户表\"&gt;\n  &lt;thead&gt;\n    &lt;tr&gt;\n      &lt;th data-col-key=\"name\"&gt;姓名&lt;/th&gt;\n      &lt;th data-col-key=\"age\"&gt;年龄&lt;/th&gt;\n      &lt;th data-col-key=\"city\"&gt;城市&lt;/th&gt;\n    &lt;/tr&gt;\n  &lt;/thead&gt;\n  &lt;tbody&gt;\n    &lt;tr data-row-index=\"0\"&gt;\n      &lt;td data-col-key=\"name\"&gt;张三&lt;/td&gt;\n      &lt;td data-col-key=\"age\"&gt;25&lt;/td&gt;\n      &lt;td data-col-key=\"city\"&gt;北京&lt;/td&gt;\n    &lt;/tr&gt;\n  &lt;/tbody&gt;\n&lt;/table&gt;</code></pre></div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>识别层级</strong></td><td>Layer 3（css class）+ Layer 4（结构推断）</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>dataGrid</code></td></tr>\n        <tr><td><strong>rowIndex / colKey</strong></td><td>自动从 tr/td 位置和 th 的 data-col-key 推断</td></tr>\n        <tr><td><strong>colName</strong></td><td>自动从 th 的文本或 data-col-name 推断</td></tr>\n      </table>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">点击单元格后上报的事件数据</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  \"action\": \"click\",\n  \"targetId\": \"grid_users\",\n  \"ctrlType\": \"dataGrid\",\n  \"customname\": \"用户表\",\n  \"basictype\": \"数据表格\",\n  \"source\": \"css\",\n  \"data\": {\n    \"rowIndex\": 0,             <span style=\"color:#2e7d32\">← 自动计算行索引</span>\n    \"colKey\": \"age\",           <span style=\"color:#2e7d32\">← 来自 th 的 data-col-key</span>\n    \"colName\": \"年龄\",         <span style=\"color:#2e7d32\">← 自动从 th 文本推断</span>\n    \"value\": \"25\"\n  }\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.dataGrid.setCellValue('grid_users', 0, 'name', '李四')</code> — 设置单元格<br/>\n        <code>webviewBridge.api.dataGrid.getCellValue('grid_users', 0, 'name')</code> — 获取单元格<br/>\n        <code>webviewBridge.api.dataGrid.addRow('grid_users', ['王五','30','上海'])</code> — 添加行<br/>\n        <code>webviewBridge.api.dataGrid.getRowCount('grid_users')</code> — 获取行数\n      </div>\n\n      <!-- 7.3 树形框 -->\n      <h4 style=\"margin-top:16px\">7.3 树形框(TreeView)</h4>\n      <p>使用约定的CSS class结构（Layer 3）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — CSS class 约定写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;div id=\"tree_files\" class=\"treeView\" data-ctrl-type=\"treeView\" data-name=\"文件树\"&gt;\n  &lt;div class=\"treeView_node\" data-node-id=\"1\"&gt;\n    &lt;span class=\"treeView_toggle\"&gt;▾&lt;/span&gt;\n    &lt;span class=\"treeView_label\"&gt;文件夹A&lt;/span&gt;\n    &lt;div class=\"treeView_children\"&gt;\n      &lt;div class=\"treeView_node\" data-node-id=\"1-1\"&gt;\n        &lt;span class=\"treeView_label\"&gt;文件1.txt&lt;/span&gt;\n      &lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n&lt;/div&gt;</code></pre></div>\n      <!-- ⚠️ 新增警告 -->\n      <div class=\"warn-box\">\n        <strong>⚠️ 关键提醒：</strong>树形框根容器 <strong>必须</strong> 添加 <code>data-ctrl-type=\"treeView\"</code>，否则深层节点点击可能取不到 <code>nodeId</code>。此属性不影响识别，但影响数据提取。\n      </div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>识别层级</strong></td><td>Layer 3（css）— 通过 treeView class 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>treeView</code></td></tr>\n      </table>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.treeView.addNode('tree_files', '1', '子节点')</code> — 添加节点<br/>\n        <code>webviewBridge.api.treeView.getSelectedNode('tree_files')</code> — 获取选中节点ID\n      </div>\n\n      <!-- 7.4 标签页 -->\n      <h4 style=\"margin-top:16px\">7.4 标签页(TabContainer)</h4>\n      <p>使用约定的CSS class结构（Layer 3）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — CSS class 约定写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;div id=\"tabs_main\" class=\"tabsContainer\" data-name=\"主标签页\"&gt;\n  &lt;div class=\"tabsContainer_headerBar\"&gt;\n    &lt;div class=\"tabsContainer_headerBar_btn\" data-tab-id=\"tab1\"&gt;标签1&lt;/div&gt;\n    &lt;div class=\"tabsContainer_headerBar_btn\" data-tab-id=\"tab2\"&gt;标签2&lt;/div&gt;\n  &lt;/div&gt;\n  &lt;div class=\"tabsContainer_contentWrapper\"&gt;\n    &lt;div data-tab-id=\"tab1\"&gt;内容1&lt;/div&gt;\n    &lt;div data-tab-id=\"tab2\"&gt;内容2&lt;/div&gt;\n  &lt;/div&gt;\n&lt;/div&gt;</code></pre></div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>识别层级</strong></td><td>Layer 3（css）— 通过 tabsContainer class 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>tabContainer</code></td></tr>\n      </table>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.tabContainer.selectTab('tabs_main', 'tab2')</code> — 切换标签<br/>\n        <code>webviewBridge.api.tabContainer.getActiveTab('tabs_main')</code> — 获取当前标签ID\n      </div>\n\n      <!-- 7.5 卡片框 -->\n      <h4 style=\"margin-top:16px\">7.5 卡片框(CardBox)</h4>\n      <p>使用约定的CSS class结构（Layer 3）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — CSS class 约定写法</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;div id=\"card_info\" class=\"cardBox\" data-ctrl-type=\"cardBox\" data-name=\"信息卡片\"&gt;\n  &lt;div class=\"cardBox_header\"&gt;\n    &lt;span class=\"cardBox_header_title\"&gt;基本信息&lt;/span&gt;\n    &lt;span class=\"cardBox_collapse_btn\"&gt;−&lt;/span&gt;\n  &lt;/div&gt;\n  &lt;div class=\"cardBox_body\"&gt;\n    卡片内容...\n  &lt;/div&gt;\n&lt;/div&gt;</code></pre></div>\n      <!-- ⚠️ 新增警告 -->\n      <div class=\"warn-box\">\n        <strong>⚠️ 关键提醒：</strong>卡片框根容器 <strong>必须</strong> 添加 <code>data-ctrl-type=\"cardBox\"</code>，否则点击折叠按钮时上报的 <code>data.collapsed</code> 状态会丢失。此属性不影响识别，但影响数据提取。\n      </div>\n      <table>\n        <tr><td style=\"width:160px\"><strong>识别层级</strong></td><td>Layer 3（css）— 通过 cardBox class 识别</td></tr>\n        <tr><td><strong>ctrlType</strong></td><td><code>cardBox</code></td></tr>\n      </table>\n      <div class=\"info-box\">\n        <strong>常用API：</strong>\n        <code>webviewBridge.api.cardBox.setCardTitle('card_info', '新标题')</code> — 设置标题<br/>\n        <code>webviewBridge.api.cardBox.collapseCard('card_info')</code> / expandCard — 折叠/展开\n      </div>\n\n      <h4 style=\"margin-top:20px\">第八步：CSS样式约定速查</h4>\n      <p>需要特定CSS class才能被Layer 3识别的控件汇总：</p>\n      <table>\n        <thead><tr><th>控件</th><th>容器class</th><th>子元素class</th><th>说明</th></tr></thead>\n        <tbody>\n          <tr><td>列表框</td><td><code>listBox</code></td><td>原生 &lt;li&gt; 即可</td><td>推荐用 ul/li + class</td></tr>\n          <tr><td>数据表格</td><td><code>dataGrid</code></td><td>原生 th/td 即可</td><td>推荐用 table + class</td></tr>\n          <tr><td>树形框</td><td><code>treeView</code></td><td><code>treeView_node</code> / <code>treeView_label</code> / <code>treeView_toggle</code> / <code>treeView_children</code></td><td>需完整结构</td></tr>\n          <tr><td>标签页</td><td><code>tabsContainer</code></td><td><code>tabsContainer_headerBar</code> / <code>tabsContainer_headerBar_btn</code> / <code>tabsContainer_contentWrapper</code></td><td>需完整结构</td></tr>\n          <tr><td>卡片框</td><td><code>cardBox</code></td><td><code>cardBox_header</code> / <code>cardBox_header_title</code> / <code>cardBox_collapse_btn</code> / <code>cardBox_body</code></td><td>需完整结构</td></tr>\n          <tr><td>进度条</td><td><code>progressBar</code></td><td><code>progressBar_fill</code></td><td>可选，也可用原生 range</td></tr>\n          <tr><td>日志框</td><td><code>logOutput</code></td><td>内部用 &lt;div&gt; 包裹每一行</td><td>每一行自动识别</td></tr>\n        </tbody>\n      </table>\n      <div class=\"tip-box\">\n        <strong>💡 提示：</strong>基础控件（按钮、输入框、复选框等）完全不需要任何特殊class，用原生HTML标签就行。只有复杂容器控件才需要约定class来辅助识别。\n      </div>\n\n      <h4 style=\"margin-top:20px\">第九步：API 调用强制性规范</h4>\n      <p>以下规范是 <strong>必须严格遵守</strong> 的，否则会导致API调用失败或返回值异常。</p>\n\n      <div class=\"warn-box\" style=\"margin:12px 0;padding:12px;background:#fff3cd;border:1px solid #ffe58f;border-radius:6px;\">\n        <strong style=\"color:#d48806\">⚠️ 规范 1：API 返回值统一包装</strong><br/>\n        所有 API 方法的返回值都会经过 <code>formatReturnValue</code> 统一处理，<strong>规则如下：</strong>\n        <ul style=\"margin:8px 0 0 20px;line-height:1.8;\">\n          <li><code>null</code> / <code>undefined</code> → 自动转为 <strong>空字符串 <code>''</code></strong></li>\n          <li><code>boolean</code> / <code>number</code> → <strong>保持原值</strong></li>\n          <li><code>string</code> → 经过图标解码后返回</li>\n          <li><code>object</code> / <code>array</code> → 转为 <strong>JSON 字符串</strong>返回，需要自行 <code>JSON.parse()</code> 解析</li>\n        </ul>\n        <div style=\"margin-top:8px;padding:8px;background:#f5f5f5;border-radius:4px;font-size:12px;\">\n          <strong>示例：</strong><br/>\n          获取配置对象 → 返回值是 JSON 字符串，需要解析：<br/>\n          <code>var config = JSON.parse(webviewBridge.api.tooltip.getConfig('tip1'));</code>\n        </div>\n      </div>\n\n      <div class=\"info-box\" style=\"margin:12px 0;\">\n        <strong>📦 规范 2：模块层级结构</strong><br/>\n        API 统一挂载在 <code>webviewBridge.api</code> 下，各模块<strong>层级独立</strong>，无嵌套关系：\n        <table style=\"margin-top:8px;width:100%;font-size:12px;\">\n          <thead><tr style=\"background:#f5f5f5;\"><th style=\"width:30%;text-align:left;padding:6px;\">模块</th><th style=\"width:35%;text-align:left;padding:6px;\">调用路径</th><th style=\"text-align:left;padding:6px;\">说明</th></tr></thead>\n          <tbody>\n            <tr><td style=\"padding:6px;border-bottom:1px solid #eee;\">通用操作</td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><code>webviewBridge.api.public</code></td><td style=\"padding:6px;border-bottom:1px solid #eee;\">setValue / getValue / show / hide / move 等</td></tr>\n            <tr><td style=\"padding:6px;border-bottom:1px solid #eee;\">画布操作</td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><code>webviewBridge.api.canvas</code></td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><strong>独立模块</strong>，不在 public 内！setFixedCanvasSize / getTitleBarTitle 等</td></tr>\n            <tr><td style=\"padding:6px;border-bottom:1px solid #eee;\">标题栏</td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><code>webviewBridge.api.titleBar</code></td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><strong>独立模块</strong>，最大化/还原状态控制</td></tr>\n            <tr><td style=\"padding:6px;border-bottom:1px solid #eee;\">图标辅助</td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><code>webviewBridge.api.public.icon</code></td><td style=\"padding:6px;border-bottom:1px solid #eee;\">icon.parse / icon.toText（在 public 子模块下）</td></tr>\n            <tr><td style=\"padding:6px;border-bottom:1px solid #eee;\">基础控件</td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><code>webviewBridge.api.button</code> / <code>.input</code> / <code>.checkbox</code> 等</td><td style=\"padding:6px;border-bottom:1px solid #eee;\">每个控件类型一个独立模块</td></tr>\n            <tr><td style=\"padding:6px;border-bottom:1px solid #eee;\">容器控件</td><td style=\"padding:6px;border-bottom:1px solid #eee;\"><code>webviewBridge.api.listBox</code> / <code>.dataGrid</code> / <code>.treeView</code> 等</td><td style=\"padding:6px;border-bottom:1px solid #eee;\">每个控件类型一个独立模块</td></tr>\n          </tbody>\n        </table>\n        <div style=\"margin-top:8px;color:#d4380d;font-size:12px;\">\n          <strong>❌ 常见错误：</strong><code>webviewBridge.api.public.canvas</code> → 错误！canvas 是独立模块，应使用 <code>webviewBridge.api.canvas</code><br/>\n          <code>webviewBridge.api.public.titleBar</code> → 错误！titleBar 也是独立模块，应使用 <code>webviewBridge.api.titleBar</code>\n        </div>\n        <div style=\"margin-top:6px;padding:8px;background:#fff3cd;border-left:4px solid #ff9800;font-size:12px;\">\n          <strong>📌 兼容性提示：</strong><code>webviewBridge.api.public</code> 中同时存在 <code>setFixedCanvasSize</code> 和 <code>getTitleBarTitle</code> 方法，这些是<strong>旧版兼容接口</strong>，功能与独立模块相同，但<strong>推荐使用独立模块</strong>（<code>api.canvas</code> 和 <code>api.titleBar</code>），旧方法可能在后续版本中移除。\n        </div>\n      </div>\n\n      <div class=\"tip-box\">\n        <strong>✅ 规范 3：控件 ID 命名强制规范</strong>\n        <ul style=\"margin:8px 0 0 20px;line-height:1.8;\">\n          <li>所有可交互控件 <strong>必须设置唯一 id</strong>，英文小写+下划线，见名知意</li>\n          <li>推荐前缀：<code>btn_</code>(按钮) / <code>inp_</code>(输入) / <code>chk_</code>(复选) / <code>rdo_</code>(单选) / <code>sel_</code>(下拉) / <code>txt_</code>(文本域) / <code>list_</code>(列表) / <code>grid_</code>(表格) / <code>tree_</code>(树形) / <code>tabs_</code>(标签页)</li>\n          <li>id 是宿主操作控件的<strong>唯一标识</strong>，不可重复，不可为空</li>\n        </ul>\n      </div>\n\n      <div class=\"info-box\">\n        <strong>🏗️ 规范 4：页面容器建议</strong>\n        <ul style=\"margin:8px 0 0 20px;line-height:1.8;\">\n          <li>页面最外层 <strong>强烈建议</strong> 使用 <code>pageContainer</code> 容器</li>\n          <li>建议设置 <code>data-original-width</code> 和 <code>data-original-height</code> 属性（设计稿尺寸）</li>\n          <li>容器需设置 <code>position: relative</code></li>\n        </ul>\n        <div style=\"margin-top:8px;padding:8px;background:#f5f5f5;border-radius:4px;font-size:12px;\">\n          <code>&lt;div class=\"pageContainer\" data-original-width=\"800\" data-original-height=\"600\" style=\"position:relative;\"&gt; ... &lt;/div&gt;</code>\n        </div>\n        <div style=\"margin-top:4px;font-size:12px;color:#b71c1c;\">\n          <strong>⚠️ 重要：</strong>如果不使用 <code>pageContainer</code>，<code>webviewBridge.api.public.getWindowSize()</code> 将回退到 <code>document.body</code> 获取尺寸，可能导致尺寸不准确。强烈建议使用该容器以保证尺寸获取的一致性。\n        </div>\n      </div>\n\n    </div>\n\n        <!-- 三、AI 提示词模板 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">3</span>AI 开发提示词模板</h3>\n      <p>将以下提示词发给 AI（如 ChatGPT、Claude、DeepSeek），即可快速生成完整的 HTML 页面。</p>\n\n      <h4>模板 A：生成简单表单页</h4>\n            <div class=\"prompt-box\" id=\"prompt-a\">你是 webviewBridge.js 前端开发专家，请生成一个可在 WebView2 中运行的 HTML 表单页面，用于用户信息录入。\n\n<b>核心规则（必须严格遵守）：</b>\n1. 页面通过 webviewBridge.js 【改成webviewBridge.js文件路径】与宿主程序通信，HTML结构需完美契合脚本的运行和识别逻辑，脚本已存在，只需引入。\n2. <b>属性添加规则（AI必须遵循）：</b>\n   - 每个可交互控件必须设置唯一的 <b>id</b>（英文小写+下划线，如 btn_submit）。\n   - <b>强烈建议</b>为所有控件设置 <b>data-name=\"中文名\"</b>（便于宿主显示，若不设置脚本会自动推断但建议显式指定）。\n   - 基础控件（按钮、输入、下拉、复选框等）使用原生HTML标签即可，<b>不要添加 data-ctrl-type</b>（脚本通过Layer 5自动识别）。\n   - 容器控件（列表框、表格等）使用约定的CSS class（如 class=\"listBox\"），<b>不要添加 data-ctrl-type</b>（脚本通过Layer 3/4识别）。\n   - 开关控件必须设置 <b>data-ctrl-type=\"switchToggle\"</b>。\n   - 页面最外层必须使用 <b>&lt;div class=\"pageContainer\" data-original-width=\"宽度\" data-original-height=\"高度\" style=\"position:relative;\"&gt;</b> 包裹所有内容。\n   - <b>**窗口拖拽控制**</b>：`pageContainer` 必须设置 `app-region: drag; -webkit-app-region: drag;`。所有可交互控件必须设置 `data-drag-type` 属性，并在 CSS 中添加 `[data-drag-type] { app-region: no-drag; -webkit-app-region: no-drag; }`。最大化按钮（`id=\"titlebar_max\"`）的内部需包含 `&lt;span&gt;` 并设为 `drag`，且固定高宽18px，以支持 Windows 11 贴靠布局。\n \n3. <b>每个可交互控件必须设置唯一的 id 属性</b>，见名知意，推荐前缀：btn_/inp_/chk_/rdo_/sel_/txt_\n4. 所有控件交互事件会自动上报给宿主，无需手动写事件监听。\n5. <b>基础控件用原生 HTML 标签即可</b>，桥接脚本会自动识别（Layer 5）：\n   - &lt;button id=\"xxx\"&gt; → button 按钮\n   - &lt;input type=\"text\" id=\"xxx\"&gt; → inputText 输入框\n   - &lt;input type=\"password\" id=\"xxx\"&gt; → inputText 密码框\n   - &lt;input type=\"checkbox\" id=\"xxx\"&gt; → checkbox 复选框\n   - &lt;input type=\"radio\" id=\"xxx\" name=\"group\"&gt; → radio 单选框\n   - &lt;select id=\"xxx\"&gt; → comboBox 组合框\n   - &lt;textarea id=\"xxx\"&gt; → textarea 文本域\n6. <b>建议给重要控件设置 data-name=\"中文名\"</b>，不设置也会自动从 label/placeholder/文本推断\n7. 页面最外层建议使用：&lt;div class=\"pageContainer\" data-original-width=\"800\" data-original-height=\"600\" style=\"position:relative;\"&gt;...&lt;/div&gt;\n8. <b>API 返回值统一包装</b>：null/undefined→空字符串，object/array→JSON字符串（需JSON.parse解析），boolean/number→保持原值\n9. <b>canvas 是独立模块</b>：使用 webviewBridge.api.canvas（不在 public 下！），常用：setFixedCanvasSize/getTitleBarTitle\n\n<b>控件列表：</b>\n  1. 用户名字段：文本输入框，id: inp_username，placeholder: 请输入用户名\n  2. 密码字段：密码输入框，id: inp_password，placeholder: 请输入密码\n  3. 性别：单选框组，name: gender，id: rdo_male / rdo_female，选项：男/女\n  4. 城市：下拉选择框，id: sel_city，选项：北京/上海/广州/深圳\n  5. 备注：多行文本域，id: txt_remark，placeholder: 请输入备注\n  6. 同意条款：复选框，id: chk_agree，文字：我已阅读并同意用户协议\n  7. 提交按钮，id: btn_submit\n  8. 取消按钮，id: btn_cancel\n\n<b>输出要求：</b>\n  - 必须通过 &lt;script src=\"webviewBridge.js\"&gt;&lt;/script&gt; 引入桥接脚本\n  - 样式使用内联 &lt;style&gt; 标签，布局美观\n  - 所有文字使用中文\n  - 输出完整可运行的 HTML 文件<button class=\"copy-prompt\" onclick=\"copyPrompt('prompt-a')\">复制提示词</button></div>\n\n      <h4>模板 B：生成数据表格页</h4>\n            <div class=\"prompt-box\" id=\"prompt-b\">你是 webviewBridge.js 前端开发专家，请生成一个可在 WebView2 中运行的数据管理 HTML 页面。\n\n<b>核心规则（必须严格遵守）：</b>\n1. 页面通过 webviewBridge.js 【改成webviewBridge.js文件路径】与宿主程序通信，HTML结构需完美契合脚本的运行和识别逻辑，脚本已存在，只需引入。\n2. <b>属性添加规则（AI必须遵循）：</b>\n   - 每个可交互控件必须设置唯一的 <b>id</b>（英文小写+下划线，如 btn_submit）。\n   - <b>强烈建议</b>为所有控件设置 <b>data-name=\"中文名\"</b>（便于宿主显示，若不设置脚本会自动推断但建议显式指定）。\n   - 基础控件（按钮、输入、下拉、复选框等）使用原生HTML标签即可，<b>不要添加 data-ctrl-type</b>（脚本通过Layer 5自动识别）。\n   - 容器控件（列表框、表格等）使用约定的CSS class（如 class=\"listBox\"、class=\"dataGrid\"），<b>不要添加 data-ctrl-type</b>（脚本通过Layer 3/4识别）。\n   - 开关控件必须设置 <b>data-ctrl-type=\"switchToggle\"</b>。\n   - 页面最外层必须使用 <b>&lt;div class=\"pageContainer\" data-original-width=\"宽度\" data-original-height=\"高度\" style=\"position:relative;\"&gt;</b> 包裹所有内容。\n   - <b>**窗口拖拽控制**</b>：`pageContainer` 必须设置 `app-region: drag; -webkit-app-region: drag;`。所有可交互控件必须设置 `data-drag-type` 属性，并在 CSS 中添加 `[data-drag-type] { app-region: no-drag; -webkit-app-region: no-drag; }`。最大化按钮（`id=\"titlebar_max\"`）的内部需包含 `&lt;span&gt;` 并设为 `drag`，且固定高宽18px，以支持 Windows 11 贴靠布局。\n 3. <b>每个可交互控件必须设置唯一的 id 属性</b>，见名知意。\n4. 所有控件交互事件会自动上报给宿主，无需手动写事件监听。\n5. <b>数据表格用原生 &lt;table&gt; + class=\"dataGrid\"</b>（Layer 3 + Layer 4 识别）：\n   - 表头 &lt;th&gt; 设置 data-col-key=\"列标识\"，列名自动从 th 文本推断\n   - 行索引 rowIndex 自动根据 tr 位置计算，无需设置 data-row-index\n   - 列号 colKey 自动从 th 的 data-col-key 推断\n6. 建议给表格设置 data-name=\"中文名\"，不设置也会从 id 推断\n7. 页面最外层建议使用：&lt;div class=\"pageContainer\" data-original-width=\"900\" data-original-height=\"600\" style=\"position:relative;\"&gt;...&lt;/div&gt;\n8. <b>API 返回值统一包装</b>：null/undefined→空字符串，object/array→JSON字符串（需JSON.parse解析），boolean/number→保持原值\n9. <b>canvas 是独立模块</b>：使用 webviewBridge.api.canvas（不在 public 下！），常用：setFixedCanvasSize/getTitleBarTitle\n\n<b>页面布局：</b>\n  - 顶部工具栏：搜索输入框(id: inp_search) + 搜索按钮(id: btn_search) + 添加按钮(id: btn_add) + 删除按钮(id: btn_delete) + 刷新按钮(id: btn_refresh)\n  - 主体区域：数据表格(id: grid_users)\n\n<b>表格结构示例（参考写法，按实际数据生成）：</b>\n  &lt;table id=\"grid_users\" class=\"dataGrid\" data-name=\"用户表\"&gt;\n    &lt;thead&gt;\n      &lt;tr&gt;\n        &lt;th data-col-key=\"name\"&gt;姓名&lt;/th&gt;\n        &lt;th data-col-key=\"age\"&gt;年龄&lt;/th&gt;\n        &lt;th data-col-key=\"city\"&gt;城市&lt;/th&gt;\n        &lt;th data-col-key=\"status\"&gt;状态&lt;/th&gt;\n      &lt;/tr&gt;\n    &lt;/thead&gt;\n    &lt;tbody&gt;\n      &lt;tr&gt;&lt;td&gt;张三&lt;/td&gt;&lt;td&gt;25&lt;/td&gt;&lt;td&gt;北京&lt;/td&gt;&lt;td&gt;启用&lt;/td&gt;&lt;/tr&gt;\n      &lt;tr&gt;&lt;td&gt;李四&lt;/td&gt;&lt;td&gt;30&lt;/td&gt;&lt;td&gt;上海&lt;/td&gt;&lt;td&gt;禁用&lt;/td&gt;&lt;/tr&gt;\n    &lt;/tbody&gt;\n  &lt;/table&gt;\n\n<b>示例数据（3-5行）：</b>\n  姓名、年龄、城市、状态 四个字段\n\n<b>输出要求：</b>\n  - 必须通过 &lt;script src=\"webviewBridge.js\"&gt;&lt;/script&gt; 引入桥接脚本\n  - 样式使用内联 &lt;style&gt; 标签，表格美观带边框斑马纹\n  - 所有文字使用中文\n  - 输出完整可运行的 HTML 文件<button class=\"copy-prompt\" onclick=\"copyPrompt('prompt-b')\">复制提示词</button></div>\n\n      <h4>模板 C：生成带导航的复杂页面</h4>\n            <div class=\"prompt-box\" id=\"prompt-c\">你是 webviewBridge.js 前端开发专家，请生成一个可在 WebView2 中运行的复杂 HTML 页面，使用标签页切换不同功能模块。\n\n<b>核心规则（必须严格遵守）：</b>\n1. 页面通过 webviewBridge.js 【改成webviewBridge.js文件路径】与宿主程序通信，HTML结构需完美契合脚本的运行和识别逻辑，脚本已存在，只需引入。\n2. <b>属性添加规则（AI必须遵循）：</b>\n   - 每个可交互控件必须设置唯一的 <b>id</b>（英文小写+下划线，如 btn_submit）。\n   - <b>强烈建议</b>为所有控件设置 <b>data-name=\"中文名\"</b>（便于宿主显示，若不设置脚本会自动推断但建议显式指定）。\n   - 基础控件（按钮、输入、下拉、复选框等）使用原生HTML标签即可，<b>不要添加 data-ctrl-type</b>（脚本通过Layer 5自动识别）。\n   - 容器控件（列表框、表格、树形、标签页、卡片等）使用约定的CSS class（如 class=\"listBox\"、class=\"tabsContainer\"），<b>不要添加 data-ctrl-type</b>（脚本通过Layer 3/4识别）。\n   - 开关控件必须设置 <b>data-ctrl-type=\"switchToggle\"</b>。\n   - 页面最外层必须使用 <b>&lt;div class=\"pageContainer\" data-original-width=\"宽度\" data-original-height=\"高度\" style=\"position:relative;\"&gt;</b> 包裹所有内容。\n   - <b>**窗口拖拽控制**</b>：`pageContainer` 必须设置 `app-region: drag; -webkit-app-region: drag;`。所有可交互控件必须设置 `data-drag-type` 属性，并在 CSS 中添加 `[data-drag-type] { app-region: no-drag; -webkit-app-region: no-drag; }`。最大化按钮（`id=\"titlebar_max\"`）的内部需包含 `&lt;span&gt;` 并设为 `drag`，且固定高宽18px，以支持 Windows 11 贴靠布局。\n \n3. <b>每个可交互控件必须设置唯一的 id 属性</b>，见名知意。\n4. 所有控件交互事件会自动上报给宿主，无需手动写事件监听。\n5. <b>标签页用 CSS class 约定结构</b>（Layer 3 识别）：\n   - 容器: class=\"tabsContainer\"\n   - 头部: class=\"tabsContainer_headerBar\"\n   - 标签按钮: class=\"tabsContainer_headerBar_btn\" + data-tab-id=\"标识\"\n   - 内容容器: class=\"tabsContainer_contentWrapper\"\n   - 内容面板: data-tab-id=\"标识\"（与按钮对应）\n6. <b>列表框用原生 &lt;ul&gt;/&lt;li&gt; + class=\"listBox\"</b>（Layer 3 + Layer 4 识别）：\n   - 容器: &lt;ul class=\"listBox\" id=\"xxx\"&gt;\n   - 列表项: &lt;li data-item-id=\"1\"&gt;文字&lt;/li&gt;\n   - itemIndex 自动根据位置计算\n7. 建议给重要控件设置 data-name=\"中文名\"\n8. 页面最外层建议使用：&lt;div class=\"pageContainer\" data-original-width=\"800\" data-original-height=\"600\" style=\"position:relative;\"&gt;...&lt;/div&gt;\n9. <b>API 返回值统一包装</b>：null/undefined→空字符串，object/array→JSON字符串（需JSON.parse解析），boolean/number→保持原值\n10. <b>canvas 是独立模块</b>：使用 webviewBridge.api.canvas（不在 public 下！），常用：setFixedCanvasSize/getTitleBarTitle\n\n<b>页面布局：</b>\n  - 顶部：页面标题\n  - 主体：标签页容器（id: tabs_main），3个标签页\n\n<b>标签页1 - 基本设置：</b>\n  用户名输入框(id: inp_username)、开关(id: sw_enable, data-name=\"启用开关\")、城市下拉框(id: sel_city)、保存按钮(id: btn_save)\n\n<b>标签页2 - 数据列表：</b>\n  列表框(id: list_data, class=\"listBox\", data-name=\"数据列表\")展示3-5条示例数据\n  文本输入框(id: inp_newitem) + 添加按钮(id: btn_additem) 用于新增列表项\n\n<b>标签页3 - 关于：</b>\n  展示软件版本、作者、官网超链接(id: link_official)等信息\n\n<b>标签页结构示例（参考写法）：</b>\n  &lt;div id=\"tabs_main\" class=\"tabsContainer\" data-name=\"主标签页\"&gt;\n    &lt;div class=\"tabsContainer_headerBar\"&gt;\n      &lt;div class=\"tabsContainer_headerBar_btn\" data-tab-id=\"tab1\"&gt;基本设置&lt;/div&gt;\n      &lt;div class=\"tabsContainer_headerBar_btn\" data-tab-id=\"tab2\"&gt;数据列表&lt;/div&gt;\n      &lt;div class=\"tabsContainer_headerBar_btn\" data-tab-id=\"tab3\"&gt;关于&lt;/div&gt;\n    &lt;/div&gt;\n    &lt;div class=\"tabsContainer_contentWrapper\"&gt;\n      &lt;div data-tab-id=\"tab1\"&gt;内容1&lt;/div&gt;\n      &lt;div data-tab-id=\"tab2\"&gt;内容2&lt;/div&gt;\n      &lt;div data-tab-id=\"tab3\"&gt;内容3&lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n<b>输出要求：</b>\n  - 必须通过 &lt;script src=\"webviewBridge.js\"&gt;&lt;/script&gt; 引入桥接脚本\n  - 样式使用内联 &lt;style&gt; 标签，标签页切换有基础JS实现（可选）\n  - 所有文字使用中文\n  - 输出完整可运行的 HTML 文件<button class=\"copy-prompt\" onclick=\"copyPrompt('prompt-c')\">复制提示词</button></div>\n\n      <h4>模板 D：通用万能提示词</h4>\n      <div class=\"prompt-box\" id=\"prompt-d\">你是 webviewBridge.js 前端开发专家，请生成一个可在 WebView2 中运行的完整 HTML 页面。\n\n<b>【身份定位】</b>\n你是精通 webviewBridge.js 桥接机制的前端开发专家，擅长用最简洁的 HTML 结构实现与宿主程序的完整交互。\n\n<b>【核心规则 — 必须100%严格遵守】</b>\n1. 页面通过 webviewBridge.js 【改成webviewBridge.js文件路径】与宿主程序通信，HTML结构需完美契合脚本的运行和识别逻辑，脚本已存在，只需引入。\n2. <b>属性添加规则（AI必读，直接照做）：</b>\n   - 每个可交互控件必须设置唯一的 <b>id</b>（英文小写+下划线，如 btn_submit）。\n   - <b>强烈建议</b>为所有控件设置 <b>data-name=\"中文名\"</b>（便于宿主显示，若不设置脚本会自动推断但建议显式指定）。\n   - 基础控件（按钮、输入、下拉、复选框等）使用原生HTML标签即可，<b>不要添加 data-ctrl-type</b>（脚本通过Layer 5自动识别）。\n   - 容器控件（列表框、表格、树形、标签页、卡片）使用约定的CSS class（如 class=\"listBox\"、class=\"dataGrid\"），<b>不要添加 data-ctrl-type</b>（脚本通过Layer 3/4识别）。\n   - 开关控件（SwitchToggle）必须设置 <b>data-ctrl-type=\"switchToggle\"</b>（因为checkbox无法区分）。\n   - 页面最外层必须使用 <b>&lt;div class=\"pageContainer\" data-original-width=\"宽度\" data-original-height=\"高度\" style=\"position:relative;\"&gt;</b> 包裹所有内容。\n   - <b>**窗口拖拽控制**</b>：`pageContainer` 必须设置 `app-region: drag; -webkit-app-region: drag;`。所有可交互控件必须设置 `data-drag-type` 属性，并在 CSS 中添加 `[data-drag-type] { app-region: no-drag; -webkit-app-region: no-drag; }`。最大化按钮（`id=\"titlebar_max\"`）的内部需包含 `&lt;span&gt;` 并设为 `drag`，且固定高宽18px，以支持 Windows 11 贴靠布局。\n \n3. <b>每个可交互控件必须设置唯一 id</b>，命名规范：英文小写+下划线，见名知意。\n   推荐前缀：btn_(按钮) / inp_(输入) / chk_(复选) / rdo_(单选) / sel_(下拉) / txt_(文本域) /\n           list_(列表) / grid_(表格) / tree_(树形) / tabs_(标签页) / card_(卡片) /\n           progress_(进度) / lbl_(标签) / link_(链接) / img_(图片) / sw_(开关)\n4. <b>绝对不要手动写任何事件监听</b>（onclick/onchange等），所有交互由桥接脚本自动捕获上报。\n5. 必须引入：&lt;script src=\"webviewBridge.js\"&gt;&lt;/script&gt;\n6. 页面最外层建议使用 pageContainer 容器：\n   &lt;div class=\"pageContainer\" data-original-width=\"页面宽度\" data-original-height=\"页面高度\" style=\"position:relative;\"&gt;...&lt;/div&gt;\n\n<b>【五层智能识别机制】</b>\n控件类型自动识别，优先级从高到低：\n- Layer 1: data-ctrl-type 属性（显式声明，最高优先级，兼容旧版，简单控件不要用）\n- Layer 2: ARIA role 属性（语义化识别，无障碍友好）\n- Layer 3: CSS class 约定命名（复杂容器控件推荐用）\n- Layer 4: DOM 结构特征推断（ul/li、table等自动识别）\n- Layer 5: 原生 HTML 标签（基础控件推荐用，零配置）\n\n<b>【智能辅助数据 — 自动填充】</b>\n- customname（控件中文名）：自动从 data-name → aria-label → 关联label → placeholder → 元素文本 → title/alt → id 推断\n  💡 建议：重要控件手动设置 data-name=\"中文名\"，最准确\n- basictype（基础类型中文名）：自动从 data-type → ctrlType中文映射 推断\n- source（识别来源）：自动标记是哪一层识别到的\n\n<b>【基础控件 — 推荐用原生标签（Layer 5），不加 data-ctrl-type】</b>\n   &lt;button id=\"xxx\" data-name=\"显示名\"&gt;文字&lt;/button&gt;           → button 按钮\n   &lt;input type=\"text\" id=\"xxx\" placeholder=\"提示\"&gt;              → inputText 输入框\n   &lt;input type=\"password\" id=\"xxx\"&gt;                              → inputText 密码框\n   &lt;input type=\"checkbox\" id=\"xxx\"&gt; 文字                         → checkbox 复选框\n   &lt;input type=\"radio\" id=\"xxx\" name=\"组名\"&gt; 文字               → radio 单选框\n   &lt;select id=\"xxx\"&gt;&lt;option value=\"v\"&gt;文字&lt;/option&gt;&lt;/select&gt; → comboBox 组合框\n   &lt;textarea id=\"xxx\" placeholder=\"提示\" rows=\"4\"&gt;&lt;/textarea&gt;   → textarea 文本域\n   &lt;a href=\"#\" id=\"xxx\"&gt;文字&lt;/a&gt;                                 → hyperLink 超链接\n   &lt;img id=\"xxx\" src=\"url\" alt=\"描述\"&gt;                           → imageBox 图片框\n   &lt;span id=\"xxx\"&gt;文字&lt;/span&gt;                                    → label 文本标签\n   &lt;input type=\"range\" id=\"xxx\" min=\"0\" max=\"100\"&gt;              → progressBar 进度条\n   &lt;input type=\"date\" id=\"xxx\"&gt;                                  → datetimePicker 日期\n\n<b>【复杂控件 — 推荐用 CSS class 约定（Layer 3），不加 data-ctrl-type】</b>\n\n▸ 列表框 listBox（也支持原生 ul/li 结构推断）：\n  &lt;ul id=\"list_xxx\" class=\"listBox\" data-name=\"列表名\"&gt;\n    &lt;li data-item-id=\"1\"&gt;项1&lt;/li&gt;\n    &lt;li data-item-id=\"2\"&gt;项2&lt;/li&gt;\n  &lt;/ul&gt;\n  👉 itemIndex 自动计算，无需手动设置\n\n▸ 数据表格 dataGrid（也支持原生 table 结构推断）：\n  &lt;table id=\"grid_xxx\" class=\"dataGrid\" data-name=\"表格名\"&gt;\n    &lt;thead&gt;&lt;tr&gt;\n      &lt;th data-col-key=\"col1\"&gt;列名1&lt;/th&gt;\n      &lt;th data-col-key=\"col2\"&gt;列名2&lt;/th&gt;\n    &lt;/tr&gt;&lt;/thead&gt;\n    &lt;tbody&gt;\n      &lt;tr&gt;&lt;td&gt;值1&lt;/td&gt;&lt;td&gt;值2&lt;/td&gt;&lt;/tr&gt;\n    &lt;/tbody&gt;\n  &lt;/table&gt;\n  👉 rowIndex / colKey / colName 全部自动推断\n\n▸ 树形框 treeView：\n  容器 class=\"treeView\"（<b>必须加 data-ctrl-type=\"treeView\"</b>，否则 nodeId 可能取不到）\n  节点 class=\"treeView_node\" data-node-id=\"xxx\"\n  标签 class=\"treeView_label\"\n  展开按钮 class=\"treeView_toggle\"\n  子容器 class=\"treeView_children\"\n\n▸ 标签页 tabsContainer：\n  容器 class=\"tabsContainer\"\n  头部 class=\"tabsContainer_headerBar\"\n  标签按钮 class=\"tabsContainer_headerBar_btn\" data-tab-id=\"xxx\"\n  内容区 class=\"tabsContainer_contentWrapper\"\n  内容面板 data-tab-id=\"xxx\"（与按钮对应）\n\n▸ 卡片框 cardBox：\n  容器 class=\"cardBox\"（<b>必须加 data-ctrl-type=\"cardBox\"</b>，否则 collapsed 状态丢失）\n  头部 class=\"cardBox_header\"\n  标题 class=\"cardBox_header_title\"\n  折叠按钮 class=\"cardBox_collapse_btn\"\n  内容区 class=\"cardBox_body\"\n\n▸ 进度条 progressBar（可选，也可用原生range）：\n  &lt;div id=\"xxx\" class=\"progressBar\" data-ctrl-type=\"progressBar\" data-editable=\"true\"&gt;\n    &lt;div class=\"progressBar_fill\" style=\"width:60%\"&gt;&lt;/div&gt;\n    &lt;span class=\"progressBar_text\"&gt;60%&lt;/span&gt;\n  &lt;/div&gt;\n  <b>（必须加 data-ctrl-type=\"progressBar\"，否则 value 始终为 0）</b>\n\n▸ 日志框 logOutput：\n  &lt;div id=\"xxx\" class=\"logOutput\" data-name=\"日志\"&gt;\n    &lt;div&gt;[INFO] 日志内容&lt;/div&gt;\n  &lt;/div&gt;\n\n<b>【⚠️ 特殊提醒 — 开关控件】</b>\n开关 switchToggle 必须显式声明 data-ctrl-type=\"switchToggle\"（因为原生 checkbox 和开关HTML无法区分）：\n  &lt;label id=\"sw_xxx\" data-ctrl-type=\"switchToggle\" data-name=\"开关名\"&gt;\n    &lt;input type=\"checkbox\"&gt; 文字\n  &lt;/label&gt;\n\n<b>【⚠️ API 调用强制性规范 — 必须遵守】</b>\n\n▸ 规范 1：API 返回值统一包装\n所有 API 方法的返回值都会经过 formatReturnValue 统一处理，规则如下：\n- null / undefined → 自动转为空字符串 ''\n- boolean / number → 保持原值\n- string → 经过图标解码后返回\n- object / array → 转为 JSON 字符串返回，需要自行 JSON.parse() 解析\n示例：var config = JSON.parse(webviewBridge.api.tooltip.getConfig('tip1'));\n\n▸ 规范 2：模块层级结构（非常重要！）\nAPI 统一挂载在 webviewBridge.api 下，各模块层级独立，无嵌套关系：\n- 通用操作：webviewBridge.api.public（setValue/getValue/show/hide/move 等）\n- 画布操作：webviewBridge.api.canvas（独立模块！不在 public 内！setFixedCanvasSize/getTitleBarTitle 等）\n- 标题栏操作：webviewBridge.api.titleBar（独立模块！maximize/restore/isMaximized 等）\n- 图标辅助：webviewBridge.api.public.icon（icon.parse/icon.toText，在 public 子模块下）\n- 基础控件：webviewBridge.api.button / .input / .checkbox 等（每个控件类型一个独立模块）\n- 容器控件：webviewBridge.api.listBox / .dataGrid / .treeView 等\n❌ 常见错误：webviewBridge.api.public.canvas → 错误！canvas 是独立模块，应使用 webviewBridge.api.canvas\n\n▸ 规范 3：控件 ID 命名强制规范\n- 所有可交互控件必须设置唯一 id，英文小写+下划线，见名知意\n- 推荐前缀：btn_(按钮) / inp_(输入) / chk_(复选) / rdo_(单选) / sel_(下拉) / txt_(文本域) /\n           list_(列表) / grid_(表格) / tree_(树形) / tabs_(标签页) / card_(卡片) /\n           progress_(进度) / lbl_(标签) / link_(链接) / img_(图片) / sw_(开关)\n- id 是宿主操作控件的唯一标识，不可重复，不可为空\n\n▸ 规范 4：页面容器建议\n- 页面最外层建议使用 pageContainer 容器\n- 建议设置 data-original-width 和 data-original-height 属性（设计稿尺寸）\n- 容器需设置 position: relative\n示例：&lt;div class=\"pageContainer\" data-original-width=\"800\" data-original-height=\"600\" style=\"position:relative;\"&gt; ... &lt;/div&gt;\n\n<b>【宿主与页面的交互方式】</b>\n- 事件上报：用户操作控件时，桥接脚本自动通过 window.chrome.webview.postMessage 上报事件给宿主，包含 targetId/ctrlType/customname/source/data 等字段。\n- 直接 API 调用：页面内 JS 可直接通过 webviewBridge.api.模块名.方法名(id, ...args) 调用（同步执行，返回结果经过统一包装）。\n- 宿主命令执行：当前版本暂不支持宿主通过 PostWebMessageAsJson 发送命令驱动页面，如有需求请在 webviewBridge.js 中自行补充命令分发逻辑。\n\n<b>【输出要求】</b>\n- 完整可运行的 HTML 文件\n- 样式使用内联 &lt;style&gt; 标签，界面美观\n- 所有文字使用中文\n- 代码结构清晰，缩进规范\n\n请根据用户需求，严格按照上述规则生成页面。<button class=\"copy-prompt\" onclick=\"copyPrompt('prompt-d')\">复制提示词</button></div>\n    </div>\n\n        <!-- 四、控件开发基础规则 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">4</span>控件开发基础规则</h3>\n\n      <h4>4.1 属性规范</h4>\n      <table>\n        <thead><tr><th>属性</th><th>必填</th><th>说明</th><th>示例</th></tr></thead>\n        <tbody>\n          <tr><td><code>id</code></td><td><span class=\"tag tag-required\">必填</span></td><td>控件唯一标识，宿主通过此 ID 发送命令和接收事件</td><td><code>id=\"btnSave\"</code></td></tr>\n          <tr><td><code>data-name</code></td><td><span class=\"tag tag-optional\">推荐</span></td><td>控件中文名称，显示在事件日志中。不设置会自动从 label/placeholder/文本推断</td><td><code>data-name=\"保存按钮\"</code></td></tr>\n          <tr><td><code>data-type</code></td><td><span class=\"tag tag-optional\">可选</span></td><td>基础类型中文名。不设置会自动从 ctrlType 映射中文名称</td><td><code>data-type=\"按钮\"</code></td></tr>\n          <!-- 修改点 ①：data-ctrl-type 行 -->\n          <tr>\n            <td><code>data-ctrl-type</code></td>\n            <td>\n              <span class=\"tag tag-required\">部分必填</span>\n              <span style=\"font-size:11px;color:#666;display:block;margin-top:2px;\">（详见 4.4 表）</span>\n            </td>\n            <td>\n              <strong>识别层：</strong>可选（五层智能识别可自动推断）。<br>\n              <strong style=\"color:#d48806;\">⚠️ 数据提取层：</strong>进度条、卡片框、树形框的<strong>根容器必须设置</strong>，否则点击上报的 <code>value</code>/<code>collapsed</code>/<code>nodeId</code> 等字段将缺失。\n            </td>\n            <td><code>data-ctrl-type=\"progressBar\"</code></td>\n          </tr>\n          <tr><td><code>aria-label</code></td><td><span class=\"tag tag-optional\">可选</span></td><td>无障碍标签，同时会被用作 customname（Layer 2）</td><td><code>aria-label=\"保存\"</code></td></tr>\n          <tr><td><code>role</code></td><td><span class=\"tag tag-optional\">可选</span></td><td>ARIA 语义化角色，用于控件识别（Layer 2）</td><td><code>role=\"button\"</code></td></tr>\n          <tr><td><code>data-editable</code></td><td><span class=\"tag tag-optional\">可选</span></td><td>是否可编辑（如进度条可点击调整）</td><td><code>data-editable=\"true\"</code></td></tr>\n          <tr><td><code>data-drag-type</code></td><td><span class=\"tag tag-required\">必填</span></td><td>标记控件为可交互元素，用于 CSS 统一设置 <code>app-region: no-drag</code>。建议每个控件都添加此属性，值通常与控件类型相同（如 <code>button</code>、<code>inputText</code>）。</td><td><code>data-drag-type=\"button\"</code></td></tr>\n        </tbody>\n      </table>\n\n            <div class=\"info-box\" style=\"margin-top:12px;\">\n        <strong>🤖 AI开发指令（给AI的明确要求）</strong><br/>\n        当AI生成HTML代码时，必须严格遵循以下属性添加规则：\n        <ul style=\"margin:6px 0 0 20px;line-height:1.8;\">\n          <li><strong>每个可交互控件必须有唯一的 <code>id</code></strong>（使用英文小写+下划线，如 <code>btn_submit</code>）。</li>\n          <li><strong>推荐为所有控件设置 <code>data-name=\"中文名\"</code></strong>（便于宿主显示和调试，若不设置脚本会自动推断，但建议显式指定）。</li>\n          <li><strong>基础控件（按钮、输入、下拉、复选框等）使用原生HTML标签即可</strong>，<strong>无需添加 <code>data-ctrl-type</code></strong>（脚本通过Layer 5自动识别）。</li>\n          <li><strong>容器控件（列表框、表格、树形、标签页、卡片）必须使用约定的CSS class</strong>（如 <code>class=\"listBox\"</code>、<code>class=\"dataGrid\"</code> 等），<strong>无需添加 <code>data-ctrl-type</code></strong>（脚本通过Layer 3/4识别）。</li>\n          <li><strong>开关控件（SwitchToggle）必须显式设置 <code>data-ctrl-type=\"switchToggle\"</code></strong>（因为checkbox无法区分普通复选框和开关）。</li>\n          <li><strong>所有控件都应设置 <code>data-name</code> 以提供友好的中文名称</strong>，但非强制（脚本会从label/placeholder/文本自动推断）。</li>\n          <li><strong>页面最外层必须使用 <code>&lt;div class=\"pageContainer\" data-original-width=\"...\" data-original-height=\"...\" style=\"position:relative;\"&gt;</code></strong> 包裹所有内容，以确保尺寸获取准确。</li>\n        </ul>\n        <div style=\"margin-top:6px;background:#f0f8ff;padding:8px;border-radius:4px;font-size:12px;\">\n          <strong>✅ 总结：</strong>AI只需关注“id唯一、data-name推荐、容器class约定、开关显式声明、pageContainer外框”五点，其余交给脚本的智能识别。\n        </div>\n      </div>\n\n\n      <h4>4.2 命名规范</h4>\n      <ul>\n        <li><strong>id 命名</strong>：英文小写 + 下划线 + 序号，如 <code>button_1</code>、<code>input_name</code>、<code>listBox_main</code></li>\n        <li><strong>全局唯一</strong>：同一页面中每个控件的 id 不能重复</li>\n        <li><strong>见名知意</strong>：命名应能反映控件用途，便于宿主端识别和处理</li>\n      </ul>\n      <div class=\"warn-box\">\n        <strong>重要：</strong>id 是控件的唯一标识。宿主通过 id 发送命令（如 <code>setValue</code>、<code>getValue</code>），事件上报也返回此 id。如果两个控件 id 重复，会导致命令执行到错误的控件上。\n      </div>\n\n      <h4>4.3 控件类型速查表</h4>\n      <table>\n        <thead><tr><th>控件名称</th><th>推荐写法（原生HTML）</th><th>识别层级</th><th>ctrlType 值</th><th>customname来源</th></tr></thead>\n        <tbody>\n          <tr><td>按钮</td><td><code>&lt;button id=\"btn1\"&gt;文字&lt;/button&gt;</code></td><td>Layer 5 native</td><td>button</td><td>按钮文字</td></tr>\n          <tr><td>输入框</td><td><code>&lt;input type=\"text\" id=\"inp1\" placeholder=\"提示\"&gt;</code></td><td>Layer 5 native</td><td>inputText</td><td>placeholder / label</td></tr>\n          <tr><td>密码框</td><td><code>&lt;input type=\"password\" id=\"pwd1\"&gt;</code></td><td>Layer 5 native</td><td>inputText</td><td>label文字</td></tr>\n          <tr><td>文本域</td><td><code>&lt;textarea id=\"txt1\" placeholder=\"提示\"&gt;&lt;/textarea&gt;</code></td><td>Layer 5 native</td><td>textarea</td><td>placeholder / label</td></tr>\n          <tr><td>复选框</td><td><code>&lt;label&gt;&lt;input type=\"checkbox\" id=\"chk1\"&gt;文字&lt;/label&gt;</code></td><td>Layer 5 native</td><td>checkbox</td><td>label文字 / 后续文本</td></tr>\n          <tr><td>单选框</td><td><code>&lt;input type=\"radio\" id=\"rdo1\" name=\"g1\"&gt;</code></td><td>Layer 5 native</td><td>radio</td><td>label文字 / 后续文本</td></tr>\n          <tr><td>组合框</td><td><code>&lt;select id=\"sel1\"&gt;&lt;option&gt;...&lt;/option&gt;&lt;/select&gt;</code></td><td>Layer 5 native</td><td>comboBox</td><td>label文字 / 选中项文字</td></tr>\n          <tr><td>超链接</td><td><code>&lt;a href=\"#\" id=\"link1\"&gt;文字&lt;/a&gt;</code></td><td>Layer 5 native</td><td>hyperLink</td><td>链接文字</td></tr>\n          <tr><td>图片框</td><td><code>&lt;img id=\"img1\" alt=\"描述\"&gt;</code></td><td>Layer 5 native</td><td>imageBox</td><td>alt / title</td></tr>\n          <tr><td>进度条</td><td><code>&lt;input type=\"range\" id=\"prg1\"&gt;</code></td><td>Layer 5 native</td><td>progressBar</td><td>label文字</td></tr>\n          <tr><td>日期选择</td><td><code>&lt;input type=\"date\" id=\"dt1\"&gt;</code></td><td>Layer 5 native</td><td>datetimePicker</td><td>label文字</td></tr>\n          <tr><td>开关</td><td><code>&lt;label id=\"sw1\" data-ctrl-type=\"switchToggle\"&gt;&lt;input type=\"checkbox\"&gt;文字&lt;/label&gt;</code></td><td>Layer 1 explicit</td><td>switchToggle</td><td>label文字</td></tr>\n          <tr><td>文本标签</td><td><code>&lt;span id=\"lbl1\"&gt;文字&lt;/span&gt;</code></td><td>Layer 5 native</td><td>label</td><td>元素文本</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"tip-box\">\n        <strong>建议：</strong>优先使用标准 HTML 标签（最左列），桥接脚本会自动识别，无需额外属性。需要精确控制类型时再使用 <code>data-ctrl-type</code> 显式声明。标准 HTML 与显式声明可以混用。</div>\n\n            <h4>4.4 data-ctrl-type 完整参考表</h4>\n      <div class=\"info-box\">\n        <strong>💡 使用建议：</strong>\n        <ul style=\"margin:6px 0 0 20px;line-height:1.8;\">\n          <li><strong>基础控件</strong>（按钮/输入/复选框等）→ 推荐用原生标签（Layer 5），<strong>无需</strong>设置 <code>data-ctrl-type</code>。</li>\n          <li><strong>容器控件</strong>（列表/表格/树形等）→ 推荐用 CSS class 约定（Layer 3），<strong>可选</strong>设置 <code>data-ctrl-type</code> 作为保险。</li>\n          <li><strong>开关控件</strong>（SwitchToggle）→ <strong>必须</strong>设置 <code>data-ctrl-type=\"switchToggle\"</code>，因为无法从 checkbox 自动区分。</li>\n          <li><strong>子元素</strong>（列表项/单元格/树节点等）→ 通常由父容器自动推断，<strong>无需</strong>设置；若自动识别失效，可显式声明辅助。</li>\n        </ul>\n      </div>\n\n      <table>\n        <thead>\n          <tr>\n            <th style=\"width:25%;\"><code>data-ctrl-type</code> 值</th>\n            <th style=\"width:20%;\">控件名称</th>\n            <th style=\"width:20%;\">是否必须显式声明</th>\n            <th style=\"width:35%;\">说明 / 推荐场景</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td><code>button</code></td><td>按钮</td><td><span class=\"tag tag-optional\">可选</span></td><td>标准 &lt;button&gt; 标签自动识别（Layer 5）</td></tr>\n          <tr><td><code>iconButton</code></td><td>图标按钮</td><td><span class=\"tag tag-optional\">可选</span></td><td>含图标的按钮，通常 &lt;button&gt; 内嵌图标即可</td></tr>\n          <tr><td><code>inputText</code></td><td>输入框</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;input type=\"text\"&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>textarea</code></td><td>文本域</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;textarea&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>checkbox</code></td><td>复选框</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;input type=\"checkbox\"&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>radio</code></td><td>单选框</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;input type=\"radio\"&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>switchToggle</code></td><td>开关</td><td><span class=\"tag tag-required\">必须</span></td><td><strong>必须显式声明</strong>，checkbox 无法区分普通复选框和开关</td></tr>\n          <tr><td><code>comboBox</code></td><td>组合框</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;select&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>hyperLink</code></td><td>超链接</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;a&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>label</code></td><td>文本标签</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;span&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>imageBox</code></td><td>图片框</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;img&gt; 自动识别（Layer 5）</td></tr>\n          <!-- 修改点 ②：以下三行改为“必须（根容器）” -->\n          <tr><td><code>progressBar</code></td><td>进度条</td><td><span class=\"tag tag-required\">必须（根容器）</span></td><td>容器必须设置，否则 <code>data.value</code> 永远为 0</td></tr>\n          <tr><td><code>datetimePicker</code></td><td>日期选择器</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;input type=\"date\"&gt; 自动识别（Layer 5）</td></tr>\n          <tr><td><code>listBox</code></td><td>列表框</td><td><span class=\"tag tag-optional\">可选</span></td><td>推荐用 class=\"listBox\" 或原生 &lt;ul&gt; 自动识别（Layer 3/4）</td></tr>\n          <tr><td><code>listBox_item</code></td><td>列表项</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 &lt;li&gt; 或结构自动推断，无需显式</td></tr>\n          <tr><td><code>listbox_item_checkbox</code></td><td>列表项复选框</td><td><span class=\"tag tag-optional\">可选</span></td><td>位于列表项内的 checkbox，通常自动识别</td></tr>\n          <tr><td><code>dataGrid</code></td><td>数据表格</td><td><span class=\"tag tag-optional\">可选</span></td><td>推荐用 class=\"dataGrid\" 或原生 &lt;table&gt; 自动识别（Layer 3/4）</td></tr>\n          <tr><td><code>dataGrid_cell</code></td><td>表格单元格</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 &lt;td&gt; 自动推断，无需显式</td></tr>\n          <tr><td><code>dataGrid_row_checkbox</code></td><td>表格行复选框</td><td><span class=\"tag tag-optional\">可选</span></td><td>位于表格行内的 checkbox，通常自动识别</td></tr>\n          <tr><td><code>dataGrid_header</code></td><td>表格表头</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 &lt;th&gt; 或 dataGrid_header class 自动推断</td></tr>\n          <tr><td><code>treeView</code></td><td>树形框</td><td><span class=\"tag tag-required\">必须（根容器）</span></td><td>容器必须设置，否则深层节点点击可能取不到 <code>nodeId</code></td></tr>\n          <tr><td><code>treeview_node_text</code></td><td>树节点文字</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 .treeView_label 自动推断</td></tr>\n          <tr><td><code>treeview_node_toggle</code></td><td>树节点展开按钮</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 .treeView_toggle 自动推断</td></tr>\n          <tr><td><code>tabsContainer</code></td><td>标签页容器</td><td><span class=\"tag tag-optional\">可选</span></td><td>推荐用 class=\"tabsContainer\" 约定（Layer 3）</td></tr>\n          <tr><td><code>tabsContainer_headerBar_btn</code></td><td>标签页按钮</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 .tabsContainer_headerBar_btn 自动推断</td></tr>\n          <tr><td><code>cardBox</code></td><td>卡片框</td><td><span class=\"tag tag-required\">必须（根容器）</span></td><td>容器必须设置，否则折叠状态 <code>data.collapsed</code> 丢失</td></tr>\n          <tr><td><code>cardBox_body</code></td><td>卡片主体</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 .cardBox_body 自动推断</td></tr>\n          <tr><td><code>logOutput</code></td><td>日志输出框</td><td><span class=\"tag tag-optional\">可选</span></td><td>推荐用 class=\"logOutput\" 约定（Layer 3）</td></tr>\n          <tr><td><code>logOutput_item</code></td><td>日志项</td><td><span class=\"tag tag-optional\">可选</span></td><td>通常从 .logOutput_line 自动推断</td></tr>\n          <tr><td><code>canvas</code></td><td>画布</td><td><span class=\"tag tag-optional\">可选</span></td><td>&lt;canvas&gt; 自动识别（Layer 5），用于绘图区域</td></tr>\n          <tr><td><code>pageContainer</code></td><td>页面容器</td><td><span class=\"tag tag-optional\">可选</span></td><td>建议用 class=\"pageContainer\" 约定，用于布局容器</td></tr>\n          <tr><td><code>radioGroup</code></td><td>单选框组</td><td><span class=\"tag tag-optional\">可选</span></td><td>包裹多个 radio 的容器，通常用 data-name 或 id 标识</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"tip-box\">\n        <strong>💡 最佳实践：</strong>\n        <ul style=\"margin:6px 0 0 20px;line-height:1.8;\">\n          <li><strong>优先使用原生标签和 CSS class</strong>，让五层智能识别自动处理，代码更简洁。</li>\n          <li><strong>仅在以下情况使用 <code>data-ctrl-type</code></strong>：\n            <ul>\n              <li>开关控件（<code>switchToggle</code>）—— 必须</li>\n              <li>进度条、卡片框、树形框的根容器 —— 必须（数据提取依赖）</li>\n              <li>自动识别失效或产生歧义时 —— 强制修正</li>\n              <li>动态生成的 DOM 元素 —— 确保识别可靠性</li>\n              <li>第三方组件或特殊封装 —— 明确类型</li>\n            </ul>\n          </li>\n          <li>即使设置了 <code>data-ctrl-type</code>，也建议同时设置 <code>data-name</code> 以提供更好的可读性。</li>\n        </ul>\n      </div>\n\n\n      <h4>4.5 自动识别演示 — 零属性 HTML 即可工作</h4>\n      <p>下面是一个<b>只写了 id 和标准 HTML 属性</b>、完全没有 <code>data-ctrl-type</code> 的页面，所有控件仍能被正确识别：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML — 纯原生标签，零 data-ctrl-type</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html&gt;\n&lt;head&gt;&lt;meta charset=&quot;UTF-8&quot;&gt;&lt;script src=&quot;webviewBridge.js&quot;&gt;&lt;/script&gt;&lt;/head&gt;\n&lt;body&gt;\n  &lt;button id=&quot;btn_ok&quot;&gt;确定&lt;/button&gt;\n  &lt;input id=&quot;inp_name&quot; type=&quot;text&quot; placeholder=&quot;请输入姓名&quot;&gt;\n  &lt;label&gt;&lt;input id=&quot;chk_agree&quot; type=&quot;checkbox&quot;&gt; 同意协议&lt;/label&gt;\n  &lt;select id=&quot;sel_city&quot;&gt;&lt;option&gt;北京&lt;/option&gt;&lt;option&gt;上海&lt;/option&gt;&lt;/select&gt;\n  &lt;a href=&quot;#&quot; id=&quot;link_help&quot;&gt;帮助&lt;/a&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre></div>\n      <p>用户点击\"确定\"按钮时，宿主会收到如下消息（注意 <code>source</code> 和 <code>ctrlType</code> 字段）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">自动上报的 JSON 事件</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  &quot;title&quot;: &quot;页面标题&quot;,\n  &quot;action&quot;: &quot;click&quot;,\n  &quot;targetId&quot;: &quot;btn_ok&quot;,\n  &quot;ctrlType&quot;: &quot;button&quot;,      &lt;span style=&quot;color:#2e7d32&quot;&gt;← 自动识别为 button&lt;/span&gt;\n  &quot;source&quot;: &quot;native&quot;,         &lt;span style=&quot;color:#2e7d32&quot;&gt;← 检测来源：原生 HTML 标签&lt;/span&gt;\n  &quot;data&quot;: { &quot;x&quot;: 50, &quot;y&quot;: 20 },\n  &quot;timestamp&quot;: 1718000000000\n}</code></pre></div>\n      <div class=\"info-box\">\n        <strong>五层智能识别：</strong>桥接脚本按 <code>explicit</code>（显式声明）→ <code>aria</code>（ARIA语义）→ <code>css</code>（CSS类名）→ <code>structure</code>（DOM结构）→ <code>native</code>（原生标签）优先级检测。<code>source</code> 字段让宿主知道控件是通过哪一层识别的，便于做不同处理。同时 <code>customname</code> 和 <code>basictype</code> 会自动推断填充。</div>\n    </div>\n\n    <!-- 五、事件上报机制 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">5</span>事件上报机制</h3>\n      \n      <h4>5.1 自动上报</h4>\n      <p>用户与控件交互时，桥接脚本自动向宿主发送 JSON 消息，<strong>无需手动编写任何事件监听代码</strong>。</p>\n\n      <h4>5.2 上报消息格式</h4>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">JSON</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>{\n  &quot;title&quot;: &quot;页面标题&quot;,\n  &quot;action&quot;: &quot;click&quot;,\n  &quot;customname&quot;: &quot;保存按钮&quot;,\n  &quot;targetId&quot;: &quot;btnSave&quot;,\n  &quot;basictype&quot;: &quot;按钮&quot;,\n  &quot;ctrlType&quot;: &quot;button&quot;,\n  &quot;source&quot;: &quot;native&quot;,\n  &quot;data&quot;: { &quot;value&quot;: &quot;保存&quot;, &quot;mouse&quot;: &quot;left&quot;, &quot;x&quot;: 150, &quot;y&quot;: 300 },\n  &quot;timestamp&quot;: 1718425600000\n}</code></pre></div>\n\n      <h4>5.3 上报的交互类型</h4>\n      <table>\n        <thead><tr><th>action</th><th>触发时机</th><th>适用控件</th></tr></thead>\n        <tbody>\n          <tr><td><code>click</code></td><td>鼠标左键单击</td><td>所有控件</td></tr>\n          <tr><td><code>dblclick</code></td><td>鼠标左键双击</td><td>所有控件</td></tr>\n          <tr><td><code>change</code></td><td>值发生改变</td><td>输入框、下拉框、复选框、单选框、开关</td></tr>\n          <tr><td><code>focus</code></td><td>获得焦点</td><td>输入框、文本域</td></tr>\n          <tr><td><code>blur</code></td><td>失去焦点</td><td>输入框、文本域</td></tr>\n          <tr><td><code>contextmenu</code></td><td>鼠标右键点击</td><td>所有控件</td></tr>\n          <tr><td><code>mouseenter</code></td><td>鼠标移入</td><td>所有控件（需在配置中启用）</td></tr>\n          <tr><td><code>mouseleave</code></td><td>鼠标移出</td><td>所有控件（需在配置中启用）</td></tr>\n        </tbody>\n      </table>\n\n      <h4>5.4 source 溯源标记 — 五层智能识别</h4>\n      <p>每个事件消息中携带 <code>source</code> 字段，标识控件是通过哪一层识别到的：</p>\n      <table>\n        <thead><tr><th>source 值</th><th>层级</th><th>含义</th><th>示例场景</th></tr></thead>\n        <tbody>\n          <tr><td><code>explicit</code></td><td>Layer 1</td><td>通过 data-ctrl-type 显式声明</td><td>设计器导出的控件，最高优先级</td></tr>\n          <tr><td><code>aria</code></td><td>Layer 2</td><td>通过 ARIA role 语义化识别</td><td>role=\"button\"、role=\"checkbox\" 等</td></tr>\n          <tr><td><code>css</code></td><td>Layer 3</td><td>通过 CSS class 名称检测</td><td>复杂控件子元素（listBox_item、dataGrid_cell 等）</td></tr>\n          <tr><td><code>structure</code></td><td>Layer 4</td><td>通过 DOM 结构特征推断</td><td>ul/li 列表、table/tr/td 表格等</td></tr>\n          <tr><td><code>native</code></td><td>Layer 5</td><td>通过原生 HTML 标签自动推断</td><td>&lt;button&gt;、&lt;input type=\"text\"&gt; 等</td></tr>\n          <tr><td colspan=\"4\"><strong>宿主端可根据 source 判断控件的可信度：</strong>explicit &gt; aria &gt; css &gt; structure &gt; native，层级越低越符合 Web 标准。</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <!-- 六、标题栏 API (新增) -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">6</span>标题栏 API（titleBar）</h3>\n      <p>标题栏模块用于控制窗口的最大化/还原状态及图标切换，所有方法均为同步调用。</p>\n\n      <h4>6.1 API 方法列表</h4>\n      <table>\n        <thead><tr><th>方法</th><th>参数</th><th>返回值</th><th>说明</th></tr></thead>\n        <tbody>\n          <tr><td><code>maximize()</code></td><td>无</td><td>无</td><td>切换窗口至最大化状态（图标变为“还原”）</td></tr>\n          <tr><td><code>restore()</code></td><td>无</td><td>无</td><td>切换窗口至还原状态（图标变为“最大化”）</td></tr>\n          <tr><td><code>isMaximized()</code></td><td>无</td><td><code>boolean</code></td><td>返回当前是否处于最大化状态</td></tr>\n          <tr><td><code>setIcon(iconHTML)</code></td><td><code>string</code> 图标HTML</td><td>无</td><td>自定义最大化时的按钮图标（<code>_titlebarMaxIcon</code>）</td></tr>\n          <tr><td><code>setRestoreIcon(iconHTML)</code></td><td><code>string</code> 图标HTML</td><td>无</td><td>自定义还原时的按钮图标（<code>_titlebarRestoreIcon</code>）</td></tr>\n        </tbody>\n      </table>\n\n <h4>6.1.1 最大化按钮与 Windows 11 Snap Layout 兼容</h4>\n      <p>为使最大化按钮同时支持点击和 Windows 11 贴靠布局，需遵循以下结构：</p>\n      <ul>\n        <li>按钮自身 <code>data-ctrl-type=\"titlebar_max\"</code> 必须设为 <code>no-drag</code>（在 CSS 中统一处理）。</li>\n        <li>按钮内部必须包含一个 <code>&lt;span&gt;</code> 或 <code>&lt;div&gt;</code>，并单独设为 <code>drag</code>，以被系统识别为标题栏区域。(固定宽高18px)</li>\n      </ul>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">HTML + CSS 示例</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>&lt;button id=&quot;titlebar_max&quot; data-ctrl-type=&quot;titlebar_max&quot;&gt;\n  &lt;span  style=\"width: 18px;height: 18px;display: flex;align-items: center;justify-content: center;\"&gt;&lt;!-- 最大化图标 --&gt;&lt;/span&gt;\n&lt;/button&gt;\n\n&lt;style&gt;\n.pageContainer [data-ctrl-type=\"titlebar_max\"] { app-region: no-drag; -webkit-app-region: no-drag; }\n.pageContainer [data-ctrl-type=\"titlebar_max\"] span { app-region: drag; -webkit-app-region: drag; }\n&lt;/style&gt;</code></pre></div>\n      <div class=\"tip-box\"><strong>💡 说明：</strong>此设计在保留按钮点击功能的同时，激活 Windows 11 的贴靠布局菜单（鼠标悬停时弹出布局选择）。</div>\n     <h4>6.2 使用示例</h4>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">JavaScript</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>// 切换到最大化\nwebviewBridge.api.titleBar.maximize();\n\n// 切换回还原\nwebviewBridge.api.titleBar.restore();\n\n// 判断当前状态\nif (webviewBridge.api.titleBar.isMaximized()) {\n  console.log('窗口已最大化');\n}\n\n// 自定义图标\nwebviewBridge.api.titleBar.setIcon('&lt;span&gt;🖥️&lt;/span&gt;');\nwebviewBridge.api.titleBar.setRestoreIcon('&lt;span&gt;📂&lt;/span&gt;');</code></pre></div>\n      <div class=\"tip-box\">\n        <strong>💡 注意：</strong>该模块依赖于页面中存在 <code>titlebar_max</code> 和 <code>titlebar_restore</code> 等特定 id 的元素（通常由设计器自动生成）。若元素不存在，API 调用将静默失败。\n      </div>\n    </div>\n\n    <!-- 七、宿主与页面通信 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">7</span>宿主与页面通信</h3>\n\n      <h4>7.1 事件上报（已实现）</h4>\n      <p>用户操作控件时，桥接脚本自动通过 <code>window.chrome.webview.postMessage</code> 发送事件消息给宿主。</p>\n      <p>消息格式见 <strong>第五章 事件上报机制</strong>，宿主只需监听 <code>window.chrome.webview</code> 的 <code>message</code> 事件即可接收。</p>\n\n      <h4>7.2 宿主命令执行（暂不支持，可自行扩展）</h4>\n      <div class=\"warn-box\">\n        <strong>⚠️ 当前版本限制：</strong><br/>\n        <code>webviewBridge.js</code> 中 <code>listenHostMessages</code> 函数仅用于打印日志，<strong>未实现命令分发逻辑</strong>。\n        宿主通过 <code>PostWebMessageAsJson</code> 发送的 <code>command</code> 消息不会被自动执行。\n      </div>\n      <p>若您的业务需要“宿主动态调用页面 API”的能力，请按以下方式自行扩展（在 <code>webviewBridge.js</code> 中修改）：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">扩展建议（在 webviewBridge.js 中修改）</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>// 在 listenHostMessages 中添加命令分发\nwindow.chrome.webview.addEventListener('message', function(e) {\n  var cmd = typeof e.data === 'string' ? JSON.parse(e.data) : e.data;\n  if (cmd.command) {\n    // 根据 command 字段分发，例如 \"button.setText\"\n    var parts = cmd.command.split('.');\n    if (parts.length === 2) {\n      var module = parts[0];\n      var method = parts[1];\n      var targetId = cmd.targetId;\n      var value = cmd.value;\n      // 调用对应 API（需根据实际模块扩展）\n      if (module === 'button' && method === 'setText') {\n        webviewBridge.api.button.setText(targetId, value);\n      } else if (module === 'input' && method === 'setValue') {\n        webviewBridge.api.input.setValue(targetId, value);\n      }\n      // ... 其他命令\n    }\n  }\n});</code></pre></div>\n      <p>或者采用更直接的<strong>“页面内联调用”</strong>方式：在页面中通过 <code>webviewBridge.api</code> 直接调用，无需经过宿主中转。这是当前推荐的做法，简单可靠。</p>\n\n      <h4>7.3 直接 API 调用（推荐）</h4>\n      <p>所有 API 方法均为同步执行，无需等待回调，适合在页面自身的 JavaScript 逻辑中使用：</p>\n      <div class=\"code-block\" style=\"margin:8px 0\"><div class=\"code-block-header\"><span class=\"lang-label\">示例</span><button class=\"copy-btn\" onclick=\"copyCodeFromBlock(this)\">复制</button></div><pre><code>// 直接设置控件值\nwebviewBridge.api.public.setValue('input_name', '张三');\n\n// 获取值\nvar name = webviewBridge.api.input.getValue('input_name');</code></pre></div>\n    </div>\n\n    <!-- 八、调试与测试 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">8</span>调试与测试</h3>\n\n      <h4>8.1 测试文件</h4>\n      <ul>\n        <li><code>test_v2.html</code> — 新方案功能测试（覆盖零配置控件 + 声明式复杂控件 + 命令执行）</li>\n        <li><code>test_old_compat.html</code> — 旧方案兼容性测试（覆盖所有 data-ctrl-type 写法）</li>\n      </ul>\n      <p>在浏览器中打开测试文件，操作控件后查看页面底部的事件日志，验证上报消息格式是否正确。</p>\n\n      <h4>8.2 开发检查清单</h4>\n      <div class=\"checklist\">\n        <span class=\"check-item\">已引入 webviewBridge.js</span>\n        <span class=\"check-item\">每个控件有唯一 id</span>\n        <span class=\"check-item\">简单控件使用标准 HTML 标签</span>\n        <span class=\"check-item\">复杂控件使用 data-ctrl 声明</span>\n        <span class=\"check-item\">控件可点击且事件上报正常</span>\n        <span class=\"check-item\">宿主命令可正常响应</span>\n        <span class=\"check-item\">控制台无报错</span>\n        <span class=\"check-item\">中文无乱码</span>\n      </div>\n\n      <h4>8.3 常见问题</h4>\n      <table>\n        <thead><tr><th>问题</th><th>原因</th><th>解决方案</th></tr></thead>\n        <tbody>\n          <tr><td>点击控件无事件上报</td><td>id 缺失或未引入桥接脚本</td><td>检查控件是否设置了 id，检查 script 标签是否正确</td></tr>\n          <tr><td>控件事件上报了但宿主收不到</td><td>WebView2 通信未配置</td><td>检查宿主端 WebView2 的消息监听配置</td></tr>\n          <tr><td>宿主命令无效</td><td>targetId 拼写错误</td><td>检查 targetId 是否与页面上控件的 id 完全一致</td></tr>\n          <tr><td>样式错乱</td><td>CSS 冲突</td><td>给控件添加专属 class 或使用内联样式</td></tr>\n          <tr><td>复杂控件只显示空白</td><td>data-* JSON 格式错误</td><td>检查 JSON 属性值是否使用单引号包裹，内部 JSON 是否合法</td></tr>\n        <tr><td>点击控件时窗口跟着拖动</td><td>控件未设置 <code>app-region: no-drag</code> 或缺少 <code>data-drag-type</code></td><td>为控件添加 <code>data-drag-type</code> 并在 CSS 中统一设置 <code>[data-drag-type] { app-region: no-drag; }</code></td></tr>\n</tbody>\n      </table>\n    </div>\n\n    <!-- 九、快速链接 -->\n    <div class=\"dev-step\">\n      <h3><span class=\"step-num\">9</span>快速链接</h3>\n      <table>\n        <thead><tr><th style=\"width:200px\">文档 / 文件</th><th>说明</th></tr></thead>\n        <tbody>\n          <tr><td><code>开发文档_控件交互规范.md</code></td><td>详细的属性规范、AI 提示词模板、控件速查表</td></tr>\n          <tr><td><code>webviewBridge.js</code></td><td>桥接脚本 v1（稳定版）</td></tr>\n          <tr><td><code>webviewBridge_v2.js</code></td><td>桥接脚本 v2（新功能版，兼容 v1）</td></tr>\n          <tr><td><code>test_v2.html</code></td><td>v2 新方案功能测试页面</td></tr>\n          <tr><td><code>test_old_compat.html</code></td><td>v1 旧方案兼容性测试页面</td></tr>\n          <tr><td>左侧导航「通用 API」</td><td>所有控件的 API 方法详细文档</td></tr>\n          <tr><td>左侧导航「命令分发处理」</td><td>所有可用的命令分发处理</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n  </div>\n\n  <div class=\"intro-section\" id=\"intro\" style=\"display:none\">\n    <h2>欢迎使用 webviewBridge API</h2>\n    <p><code>webviewBridge</code> 是 WebView2 宿主与前端页面的桥接脚本，挂载在全局 <code>window.webviewBridge</code> 上。</p>\n    <p>提供三种通信方式：</p>\n    <p>1. <strong>直接 API 调用</strong>：<code>webviewBridge.api.button.setText('button_1', '确定')</code></p>\n    <p>2. <strong>命令分发</strong>：通过 <code>window.chrome.webview.postMessage(JSON)</code> 发送命令</p>\n    <p>3. <strong>事件监听</strong>：控件交互自动触发 <code>chrome.webview.postMessage</code> 上报事件</p>\n    <p style=\"margin-top:14px\">请从左侧导航选择控件查看详细 API 文档。每个方法均提供 <strong>API 调用示例</strong> 和 <strong>命令分发示例</strong>，代码块支持一键复制。</p>\n  </div>";